  {t="C", q=851, obj=1, name="Verog the Dervish", gv="Collect", gw="Verog's Head", z=17, x=53.06, y=41.74, note="Collect Verog's Head", tip="Verog doesn't wander on his own: he comes out when you kill the Kolkar centaurs at the Stagnant Oasis, south-east of the Crossroads. Keep killing them around the oasis until he appears. Test Tonga's seeds at the bubbling fissure on the oasis' east bank while you are there.", section="The Barrens (14-23)", zoneName="The Barrens", p=625, place="Verog the Dervish", was=1850}, -- 1852
  {t="C", q=877, obj=1, name="The Stagnant Oasis", z=17, x=55.61, y=42.75, note="Underwater", section="The Barrens (14-23)", zoneName="The Barrens", p=625, place="Verog the Dervish", was=1851}, -- 1853
  {t="C", q=6129, obj=1, name="Cure Sickly Gazelle", z=17, x=56.93, y=38.97, note="Sickly Gazelle: use the Curative Animal Salve on them; they roam the plains all around the Crossroads", races={"tauren", "skyborne"}, classes={"Druid"}, section="The Barrens (14-23)", zoneName="The Barrens", p=625, place="Verog the Dervish", was=1852}, -- 1854
  {t="C", q=4921, obj=1, name="Lost in Battle", gv="Talk to", gw="Beaten Corpse", z=17, x=49.3, y=50.3, note="Talk to Beaten Corpse", tip="The Bristleback quilboar camps spread over the plains north of Camp Taurajo, either side of the Gold Road. Mankrik's wife lies at their north edge, on your way south. Leave the quilboar for now: Mangletooth in Camp Taurajo wants the same camps cleared. Lakota'mani, a grey kodo (level 22), sometimes wanders here: his hoof starts a quest. Leave him alone below level 21.", section="The Barrens (14-23)", zoneName="The Barrens", p=626, place="Bristleback camps", was=1853}, -- 1855
  {t="A", q=878, name="Tribes at War", z=17, x=44.55, y=59.26, target={kind="npc", id=3430, name="Mangletooth"}, note="Mangletooth, in the cage", tip="Follow the Gold Road south to Camp Taurajo.", section="The Barrens (14-23)", zoneName="The Barrens", p=627, place="Camp Taurajo", was=1854}, -- 1856
  {t="FP", text="Camp Taurajo flight path", z=17, x=44.45, y=59.15, note="Omusa Thunderhorn", section="The Barrens (14-23)", zoneName="The Barrens", p=627, place="Camp Taurajo"}, -- 1857
