  {t="C", q=852, obj=1, name="Hezrul Bloodmark", gv="Collect", gw="Hezrul's Head", z=17, x=46.0, y=41.1, note="Collect Hezrul's Head", tip="Hezrul leads the Kolkar on the west shore of Lushwater Oasis, south of Regthar. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to Regthar on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for Tonga.", section="The Barrens (14-23)", zoneName="The Barrens", p=666, place="Hezrul Bloodmark", was=1960}, -- 1962
  {t="C", q=880, obj=1, name="Altered Beings", gv="Collect", gw="Altered Snapjaw Shell", z=17, x=45.93, y=40.41, note="Collect Altered Snapjaw Shell", section="The Barrens (14-23)", zoneName="The Barrens", p=666, place="Hezrul Bloodmark", was=1961}, -- 1963
  {t="C", q=95774, obj=1, name="Her Name Is Olgra", gv="Collect", gw="Olgra's Adornments", foreverOnly=true, z=17, x=49.99, y=45.18, note="Collect Olgra's Adornments", tip="On the way back down the Gold Road to Camp Taurajo: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry Olgra's Adornments. Hand them to Mankrik on your last Crossroads stop.", section="The Barrens (14-23)", zoneName="The Barrens", p=667, place="Olgra's Adornments", was=1962}, -- 1964
