  {t="A", q=913, name="Cry of the Thunderhawk", z=17, x=44.86, y=59.14, target={kind="npc", id=3387, name="Jorn Skyseer"}, section="The Barrens (14-23)", zoneName="The Barrens", p=672, place="Jorn Skyseer", was=1978}, -- 1980
  {t="T", q=884, name="Owatanka", optional=true, z=17, x=44.86, y=59.14, target={kind="npc", id=3387, name="Jorn Skyseer"}, section="The Barrens (14-23)", zoneName="The Barrens", p=672, place="Jorn Skyseer", was=1979}, -- 1981
  {t="A", q=1824, name="Trial at the Field of Giants", z=17, x=44.67, y=59.42, target={kind="npc", id=6394, name="Ruga Ragetotem"}, note="Ruga Ragetotem, inside", classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=672, place="Jorn Skyseer", was=1980}, -- 1982
  {t="C", q=1824, obj=1, name="Trial at the Field of Giants", z=17, x=45.11, y=68.95, note="Twitching Antennae from the silithid", tip="The antennae vanish fifteen minutes after they drop: kill the Silithid Swarmers and Creepers at the Silithid Mounds in the Field of Giants, south of Camp Taurajo, until you have five, then take them straight to Ruga Ragetotem in Camp Taurajo, before the thunderhawks. Careful: Silithid Swarmers (level 21-22) cast Silithid Swarm both in and out of combat, which brings several small adds; Silithid Creepers (level 20-21) periodically cast Silithid Creeper Egg in combat, which spawns extra adds. A Silithid Harvester (24, rare) also wanders the mounds: leave it.", classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=673, place="Twitching Antennae", was=1981}, -- 1983
  {t="T", q=1824, name="Trial at the Field of Giants", z=17, x=44.67, y=59.42, target={kind="npc", id=6394, name="Ruga Ragetotem"}, note="Ruga Ragetotem, inside", tip="Back north into Camp Taurajo before the antennae fade: Ruga Ragetotem is inside.", classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=674, place="Ruga Ragetotem", was=1982}, -- 1984
  {t="A", q=1825, name="Speak with Thun'grim", z=17, x=44.67, y=59.42, target={kind="npc", id=6394, name="Ruga Ragetotem"}, classes={"Warrior"}, section="The Barrens (14-23)", zoneName="The Barrens", p=674, place="Ruga Ragetotem", was=1983}, -- 1985
