  {t="A", q=1063, name="The Elder Crone", z=17, x=35.26, y=27.88, target={kind="npc", id=4049, name="Seereth Stonebreak"}, note="Seereth Stonebreak: The Elder Crone, Magatha in Thunder Bluff, on the next guide's way back from Zoram'gar", section="The Barrens (14-23)", zoneName="The Barrens", p=697, place="Seereth Stonebreak", was=2031}, -- 2033
  {t="T", q=6629, name="Kill Grundig Darkcloud", z=17, x=35.19, y=27.76, target={kind="npc", id=11857, name="Makaba Flathoof"}, note="Makaba Flathoof", section="The Barrens (14-23)", zoneName="The Barrens", p=697, place="Seereth Stonebreak", was=2032}, -- 2034
  {t="T", q=6523, name="Protect Kaya", z=17, x=35.19, y=27.76, target={kind="npc", id=11857, name="Makaba Flathoof"}, note="Makaba Flathoof", section="The Barrens (14-23)", zoneName="The Barrens", p=697, place="Seereth Stonebreak", was=2033}, -- 2035
  {t="A", q=6401, name="Kaya's Alive", z=17, x=35.19, y=27.76, target={kind="npc", id=11857, name="Makaba Flathoof"}, note="Makaba Flathoof: keep it, Tammra Windfield at Sun Rock Retreat in the Barrens & Stonetalon guide", section="The Barrens (14-23)", zoneName="The Barrens", p=697, place="Seereth Stonebreak", was=2034}, -- 2036
  {t="N", text="The next guide goes north-east across the Barrens to the Mor'shan Rampart and Ashenvale.", section="The Barrens (14-23)", p=697, place="Seereth Stonebreak"}, -- 2037
  {t="T", q=2458, name="Deep Cover", z=17, x=55.44, y=5.56, target={kind="npc", id=7233, name="Taskmaster Fizzule"}, note="Taskmaster Fizzule", tip="On the way north from Seereth's camp, keep east of the road to the Venture Co. tower north of the Sludge Fen. Before you go near Fizzule, use {item:8051} to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first.", classes={"Rogue"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="The Barrens", p=698, place="Taskmaster Fizzule", was=2036}, -- 2038
  {t="A", q=2478, name="Mission: Possible But Not Probable", optional=true, z=17, x=55.44, y=5.56, target={kind="npc", id=7233, name="Taskmaster Fizzule"}, classes={"Rogue"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="The Barrens", p=698, place="Taskmaster Fizzule", was=2037}, -- 2039
  {t="N", text="Mission: Possible But Not Probable is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde).", classes={"Rogue"}, section="Ashenvale & Silverpine Forest (22-23)", p=698, place="Taskmaster Fizzule"}, -- 2040
  {t="T", q=6541, name="Report to Kadrak", z=17, x=48.12, y=5.42, target={kind="npc", id=8582, name="Kadrak"}, note="Kadrak", tip="From Seereth's camp head north-east across the Barrens to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. Kadrak stands on the watch tower of the Mor'shan Rampart where the road enters Ashenvale.", section="Ashenvale & Silverpine Forest (22-23)", zoneName="The Barrens", p=699, place="Kadrak", was=2039}, -- 2041
  {t="G", text="The road north to Splintertree Post", z=331, x=71.1, y=68.1, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=700, place="Into Ashenvale"}, -- 2042
  {t="FP", text="Splintertree Post flight path", tip="Splintertree Post is just north up the road. Coming in from the south, the flight master and Senani Thunderheart's hunt board at Night Run come first, then the vendors. Kuray'bin at the lumber camp offers Ashenvale Outrunners: leave it for the next Ashenvale visit, at 26.", section="Ashenvale & Silverpine Forest (22-23)", p=701, place="Splintertree Post"}, -- 2043
  {t="T", q=6382, name="The Ashenvale Hunt", z=331, x=73.78, y=61.46, target={kind="npc", id=12696, name="Senani Thunderheart"}, note="Senani Thunderheart", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=701, place="Splintertree Post", was=2042}, -- 2044
  {t="T", q=6383, name="The Ashenvale Hunt", z=331, x=73.78, y=61.46, target={kind="npc", id=12696, name="Senani Thunderheart"}, direct=true, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=701, place="Splintertree Post", was=2043}, -- 2045
  {t="N", text="Senani's hunt targets Ursangous and Shadumbra are for the next Ashenvale visit, at 26; Sharptalon (31) only from level 30.", section="Ashenvale & Silverpine Forest (22-23)", p=701, place="Splintertree Post"}, -- 2046
  {t="N", text="Sell junk and repair", section="Ashenvale & Silverpine Forest (22-23)", p=701, place="Splintertree Post"}, -- 2047
  {t="C", q=6503, name="Ashenvale Outrunners", gv="Kill", gw="Ashenvale Outrunner", z=331, x=72.5, y=69.5, note="Kill Ashenvale Outrunner", tip="The night elf Ashenvale Outrunners (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them.", onQuest={6503}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=702, place="Ashenvale Outrunners", was=2319}, -- 2048
  {t="T", q=6503, name="Ashenvale Outrunners", z=331, x=71.11, y=68.12, target={kind="npc", id=12867, name="Kuray'bin"}, note="Kuray'bin", tip="Back to Kuray'bin at the lumber camp, on the road north to Splintertree.", onQuest={6503}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=703, place="Warsong lumber camp", was=2320}, -- 2049
  {t="A", q=98251, name="Never Coming Back", foreverOnly=true, z=331, x=40.4, y=61.5, target={kind="npc", id=267214, name="Va'xug Firefure"}, note="Va'xug Firefure", tip="On the way west, Va'xug Firefure is stuck in a ravine south of the main road, south-east of Astranaar. Shadowhorn Stags and Ashenvale Bears roam the woods all around it.", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=704, place="Va'xug Firefure", was=2046}, -- 2050
  {t="C", q=98251, obj=1, name="Never Coming Back", gv="Kill", gw="Shadowhorn Stag", foreverOnly=true, z=331, x=41.36, y=61.91, note="Kill Shadowhorn Stag", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=704, place="Va'xug Firefure", was=2047}, -- 2051
  {t="C", q=98251, obj=2, name="Never Coming Back", gv="Kill", gw="Ashenvale Bear", foreverOnly=true, z=331, x=41.27, y=61.95, note="Kill Ashenvale Bear", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=704, place="Va'xug Firefure", was=2048}, -- 2052
  {t="T", q=98251, name="Never Coming Back", foreverOnly=true, z=331, x=40.46, y=61.42, target={kind="npc", id=267214, name="Va'xug Firefure"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=704, place="Va'xug Firefure", was=2049}, -- 2053
  {t="A", q=98252, name="A Void Path", foreverOnly=true, z=331, x=40.46, y=61.42, target={kind="npc", id=267214, name="Va'xug Firefure"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=704, place="Va'xug Firefure", was=2050}, -- 2054
  {t="C", q=98252, name="A Void Path", foreverOnly=true, z=331, x=38.2, y=58.1, tip="Steer Va'xug's Eye of Kilrogg out of the ravine to the main road within four minutes; if the channel breaks, ask Va'xug again.", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=705, place="A Void Path", was=2051}, -- 2055
  {t="T", q=98252, name="A Void Path", foreverOnly=true, z=331, x=38.2, y=58.1, target={kind="npc", id=271181, name="Eye of Kilrogg"}, note="Eye of Kilrogg, on the road", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=705, place="A Void Path", was=2052}, -- 2056
  {t="FP", text="Zoram'gar Outpost flight path", tip="Head west along the main road across Ashenvale, past Astranaar (Alliance: keep to the road), to the coast. Zoram'gar Outpost is on the Zoram Strand in the north-west: Marukai and Muglash stand around it, the Warsong Runner beside the flight master. Its other quests, Thistlefur's among them, are for the next visit, at 26.", section="Ashenvale & Silverpine Forest (22-23)", p=706, place="Zoram'gar Outpost"}, -- 2057
  {t="A", q=6442, name="Naga at the Zoram Strand", z=331, x=11.69, y=34.91, target={kind="npc", id=12719, name="Marukai"}, note="Marukai", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=706, place="Zoram'gar Outpost", was=2054}, -- 2058
  {t="A", q=6641, name="Vorsha the Lasher", z=331, x=12.06, y=34.63, target={kind="npc", id=12717, name="Muglash"}, note="Muglash: take it last, his escort starts at once", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=706, place="Zoram'gar Outpost", was=2055}, -- 2059
  {t="G", text="Naga brazier", z=331, x=9.6, y=27.6, tip="Muglash walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads Marukai wants.", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=707, place="Vorsha the Lasher"}, -- 2060
  {t="C", q=6641, name="Vorsha the Lasher", z=331, x=9.57, y=27.56, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=707, place="Vorsha the Lasher", was=2057}, -- 2061
  {t="C", q=6442, name="Naga at the Zoram Strand", gv="Collect", gw="Wrathtail Head", z=331, x=10.79, y=27.13, note="Collect Wrathtail Head", tip="Every Wrathtail naga along the strand north of the outpost drops heads.", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=708, place="Naga heads", was=2058}, -- 2062
  {t="T", q=6641, name="Vorsha the Lasher", z=331, x=12.22, y=34.22, target={kind="npc", id=12863, name="Warsong Runner"}, note="Warsong Runner", tip="Back to the outpost.", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=709, place="Zoram'gar Outpost", was=2059}, -- 2063
  {t="T", q=6442, name="Naga at the Zoram Strand", z=331, x=11.69, y=34.91, target={kind="npc", id=12719, name="Marukai"}, note="Marukai", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Ashenvale", p=709, place="Zoram'gar Outpost", was=2060}, -- 2064
  {t="G", text="Zoram'gar Outpost flight master", z=1638, x=12.2, y=33.8, tip="The Elder Crone first: fly to Thunder Bluff from the Zoram'gar Outpost flight master. Magatha and Apothecary Zamah send you to Apothecary Lydon in Tarren Mill, the next guide's base, and Thunder Bluff's flight path takes you on to Orgrimmar.", taxi="Thunder Bluff", onQuest={1063}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Thunder Bluff", p=710, place="Fly to Thunder Bluff"}, -- 2065
  {t="F", text="Thunder Bluff", taxi="Thunder Bluff", onQuest={1063}, section="Ashenvale & Silverpine Forest (22-23)", p=710, place="Fly to Thunder Bluff"}, -- 2066
  {t="G", text="Zoram'gar Outpost flight master", z=17, x=12.2, y=33.8, tip="The Elder Crone first: fly to Camp Taurajo from the Zoram'gar Outpost flight master and walk on to Thunder Bluff. Magatha and Apothecary Zamah send you to Apothecary Lydon in Tarren Mill, the next guide's base, and Thunder Bluff's flight path takes you on to Orgrimmar.", races={"orc", "troll", "undead"}, classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock"}, notTaxi="Thunder Bluff", onQuest={1063}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="The Barrens", p=711, place="Fly to Camp Taurajo"}, -- 2067
  {t="F", text="Camp Taurajo", races={"orc", "troll", "undead"}, classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock"}, notTaxi="Thunder Bluff", onQuest={1063}, section="Ashenvale & Silverpine Forest (22-23)", p=711, place="Fly to Camp Taurajo"}, -- 2068
  {t="G", text="Thunder Bluff's central rise", z=1638, x=47.0, y=49.8, tip="From Camp Taurajo follow the road west through the gate into Mulgore, then north past Bloodhoof Village to Thunder Bluff; a lift at the foot of the bluffs takes you up.", races={"orc", "troll", "undead"}, classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock"}, notTaxi="Thunder Bluff", onQuest={1063}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Thunder Bluff", p=712, place="To Thunder Bluff"}, -- 2069
  {t="FP", text="Thunder Bluff flight path", z=1638, x=47, y=49.83, note="Tal", tip="Tal, the wind rider master, stands on the central rise: take his flight path if you don't have it. Magatha Grimtotem stands on Elder Rise to the east; Apothecary Zamah in the Pools of Vision, the caves under Spirit Rise to the west.", onQuest={1063, 1064, 1065}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Thunder Bluff", p=713, place="Thunder Bluff"}, -- 2070
  {t="T", q=1063, name="The Elder Crone", z=1638, x=69.85, y=30.91, target={kind="npc", id=4046, name="Magatha Grimtotem"}, note="Magatha Grimtotem, Elder Rise", onQuest={1063, 1064, 1065}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Thunder Bluff", p=713, place="Thunder Bluff", was=2067}, -- 2071
  {t="A", q=1064, name="Forsaken Aid", z=1638, x=69.85, y=30.91, target={kind="npc", id=4046, name="Magatha Grimtotem"}, onQuest={1063, 1064, 1065}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Thunder Bluff", p=713, place="Thunder Bluff", was=2068}, -- 2072
  {t="TR", text="Train at your class trainer", note="Turak Runetotem, Elder Rise", classes={"Druid"}, onQuest={1063, 1064, 1065}, section="Ashenvale & Silverpine Forest (22-23)", p=713, place="Thunder Bluff"}, -- 2073
  {t="T", q=1064, name="Forsaken Aid", z=1638, x=22.81, y=20.89, target={kind="npc", id=3419, name="Apothecary Zamah"}, note="Apothecary Zamah, Pools of Vision", onQuest={1063, 1064, 1065}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Thunder Bluff", p=713, place="Thunder Bluff", was=2070}, -- 2074
  {t="A", q=1065, name="Journey to Tarren Mill", z=1638, x=22.81, y=20.89, target={kind="npc", id=3419, name="Apothecary Zamah"}, note="Apothecary Zamah: her note is for Apothecary Lydon in Tarren Mill, next guide", onQuest={1063, 1064, 1065}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Thunder Bluff", p=713, place="Thunder Bluff", was=2071}, -- 2075
  {t="G", text="Thunder Bluff's central rise", z=1637, x=47.0, y=49.8, tip="Back up to Tal on the central rise and fly to Orgrimmar.", onQuest={1065}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=714, place="Fly to Orgrimmar"}, -- 2076
  {t="F", text="Orgrimmar", onQuest={1065}, section="Ashenvale & Silverpine Forest (22-23)", p=714, place="Fly to Orgrimmar"}, -- 2077
