  {t="TR", text="Train at your class trainer", classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", p=717, place="Orgrimmar"}, -- 2081
  {t="T", q=1512, name="Love's Gift", z=1637, x=48.25, y=45.28, target={kind="npc", id=5875, name="Gan'rul Bloodeye"}, tip="Gan'rul Bloodeye stands in the Cleft of Shadow. Use Dogran's Pendant on the summoning circle there and defeat the succubus to bind her.", classes={"Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=718, place="The Binding", was=2078}, -- 2082
  {t="A", q=1513, name="The Binding", z=1637, x=48.25, y=45.28, target={kind="npc", id=5875, name="Gan'rul Bloodeye"}, classes={"Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=718, place="The Binding", was=2079}, -- 2083
  {t="N", text="Use Dogran's Pendant", z=1637, x=49.4, y=50.0, note="Dogran's Pendant", classes={"Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=718, place="The Binding"}, -- 2084
  {t="C", q=1513, obj=1, name="The Binding", gv="Kill", gw="Summoned Succubus", z=1637, x=49.4, y=50.02, note="Kill Summoned Succubus", classes={"Warlock"}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=718, place="The Binding", was=2081}, -- 2085
