  {t="T", q=2478, name="Mission: Possible But Not Probable", z=1637, x=43.05, y=53.74, target={kind="npc", id=3401, name="Shenthul"}, note="Shenthul, Cleft of Shadow", tip="If you did Mission: Possible But Not Probable with a group, Shenthul in the Cleft of Shadow takes it now.", classes={"Rogue"}, ready=2478, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=719, place="Shenthul", was=2083}, -- 2087
  {t="A", q=2479, name="Hinott's Assistance", z=1637, x=43.05, y=53.74, target={kind="npc", id=3401, name="Shenthul"}, note="Serge Hinott in Tarren Mill teaches Poisons: keep it", classes={"Rogue"}, ready=2478, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Orgrimmar", p=719, place="Shenthul", was=2084}, -- 2088
  {t="G", text="Zeppelin to Undercity", z=14, x=50.8, y=13.5, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Durotar", p=720, place="Zeppelin to Undercity"}, -- 2089
  {t="TR", text="Train at your class trainer", tip="Shari Stilwell trains Paladins in Brill, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine.", classes={"Paladin"}, section="Ashenvale & Silverpine Forest (22-23)", p=721, place="Brill"}, -- 2090
  {t="N", text="Collect Half Pendant of Aquatic Endurance", note="Half Pendant of Aquatic Endurance, from the Strange Lockbox", tip="From the zeppelin towers, run south into Silverpine and west past the Dead Field to the coast: the Strange Lockbox lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the Half Pendant of Aquatic Endurance for Trial of the Sea Lion. Then on to the Sepulcher.", races={"tauren", "skyborne"}, classes={"Druid"}, onQuest={30}, section="Ashenvale & Silverpine Forest (22-23)", p=722, place="Strange Lockbox"}, -- 2091
  {t="A", q=493, name="Journey to Hillsbrad Foothills", z=130, x=42.8, y=40.86, target={kind="npc", id=1937, name="Apothecary Renferrel"}, note="Apothecary Renferrel: Lydon in Tarren Mill, next guide", tip="Down the road through Silverpine to the Sepulcher: from the zeppelin towers, south through Tirisfal; from the Strange Lockbox, south-east from the coast to the road. Shadow Priest Allister and Apothecary Renferrel stand by the crypt entrance.", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Silverpine Forest", p=723, place="The Sepulcher", was=2088}, -- 2092
  {t="A", q=95981, name="Watching the Roads", foreverOnly=true, z=130, x=43.98, y=40.93, target={kind="npc", id=2121, name="Shadow Priest Allister"}, note="Shadow Priest Allister", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Silverpine Forest", p=723, place="The Sepulcher", was=2089}, -- 2093
  {t="A", q=516, name="Beren's Peril", z=130, x=43.98, y=40.93, target={kind="npc", id=2121, name="Shadow Priest Allister"}, note="Shadow Priest Allister: Beren's Peril, south-east of Ambermill", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Silverpine Forest", p=723, place="The Sepulcher", was=2090}, -- 2094
  {t="A", q=479, name="Ambermill Investigations", z=130, x=43.98, y=40.93, target={kind="npc", id=2121, name="Shadow Priest Allister"}, note="Shadow Priest Allister: Ambermill's pendants, on the same roads", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Silverpine Forest", p=723, place="The Sepulcher", was=2091}, -- 2095
  {t="T", q=6324, name="Return to Podrig", z=130, x=43.42, y=41.68, target={kind="npc", id=6389, name="Deathguard Podrig"}, note="Deathguard Podrig", tip="Deathguard Podrig stands just west of the crypt entrance: hand him Gordon's Crate from the Undercity.", races={"undead"}, onQuest={6324}, section="Ashenvale & Silverpine Forest (22-23)", zoneName="Silverpine Forest", p=724, place="Deathguard Podrig", was=2092}, -- 2096
  {t="C", q=95981, obj=2, name="Watching the Roads", gv="Kill", gw="Dalaran Wizard", foreverOnly=true, z=130, x=64.85, y=49.82, note="Kill Dalaran Wizard", tip="South down the road past Pyrewood: Dalaran Watchers and Wizards patrol the roads around Ambermill, and south-west of the town the Ravenclaw Drudgers and Guardians haunt the ruins of Beren's Peril in the south-east of the forest. Careful: High Order Mages (30) walk the same roads among the Watchers and Wizards: leave them.", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Silverpine Forest", p=725, place="Silverpine Forest: kill these as you meet them", was=2093}, -- 2097
  {t="C", q=95981, obj=1, name="Watching the Roads", gv="Kill", gw="Dalaran Watcher", foreverOnly=true, z=130, x=65.17, y=56.32, note="Kill Dalaran Watcher", section="Ashenvale & Silverpine Forest (22-23)", zoneName="Silverpine Forest", p=725, place="Silverpine Forest: kill these as you meet them", was=2094}, -- 2098
