  {t="T", q=2479, name="Hinott's Assistance", z=267, x=61.63, y=19.19, target={kind="npc", id=2391, name="Serge Hinott"}, note="Serge Hinott", tip="After returning Mission: Possible But Not Probable to Shenthul, bring Hinott's Assistance to Serge Hinott in Tarren Mill. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill.", classes={"Rogue"}, section="Hillsbrad Foothills (22-25)", zoneName="Hillsbrad Foothills", p=732, place="Serge Hinott", was=2122}, -- 2126
  {t="A", q=2480, name="Hinott's Assistance", optional=true, z=267, x=61.63, y=19.19, target={kind="npc", id=2391, name="Serge Hinott"}, classes={"Rogue"}, section="Hillsbrad Foothills (22-25)", zoneName="Hillsbrad Foothills", p=732, place="Serge Hinott", was=2123}, -- 2127
