  {t="T", q=1096, name="Gerenzo Wrenchwhistle", z=406, x=58.99, y=62.6, target={kind="npc", id=4201, name="Ziz Fizziks"}, note="Ziz Fizziks, inside", tip="Back west to Ziz Fizziks' hut, on the way down to Malaka'jin.", ready=1096, section="The Barrens & Stonetalon Mountains (24-27)", zoneName="Stonetalon Mountains", p=801, place="Ziz Fizziks", was=2289}, -- 2293
  {t="T", q=1058, name="Jin'Zil's Forest Magic", z=406, x=74.54, y=97.94, target={kind="npc", id=3995, name="Witch Doctor Jin'Zil"}, note="Witch Doctor Jin'Zil, below ground", tip="On down the Webwinder Path to Malaka'jin.", section="The Barrens & Stonetalon Mountains (24-27)", zoneName="Stonetalon Mountains", p=802, place="Malaka'jin", was=2290}, -- 2294
