  {t="A", q=216, name="Between a Rock and a Thistlefur", z=331, x=11.9, y=34.54, target={kind="npc", id=12757, name="Karang Amakkar"}, note="Karang Amakkar", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=805, place="Zoram'gar Outpost", was=2297}, -- 2301
