  {t="G", text="Blackfathom Deeps ruins", z=331, x=14.5, y=14.2, tip="The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=806, place="Blackfathom Deeps ruins"}, -- 2303
  {t="C", q=6563, name="The Essence of Aku'Mai", gv="Collect", gw="Sapphire of Aku'Mai", z=331, x=13.59, y=13.14, note="Collect Sapphire of Aku'Mai", tip="The Sapphires are blue crystals on the walls of the tunnels leading to the Blackfathom Deeps portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=807, place="Sapphires of Aku'Mai", was=2300}, -- 2304
  {t="C", q=216, obj=1, name="Between a Rock and a Thistlefur", gv="Kill", gw="Thistlefur Avenger", z=331, x=35.78, y=32.01, note="Kill Thistlefur Avenger", tip="Careful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=808, place="Thistlefur Village", was=2301}, -- 2305
  {t="C", q=216, obj=2, name="Between a Rock and a Thistlefur", gv="Kill", gw="Thistlefur Shaman", z=331, x=35.83, y=31.74, note="Kill Thistlefur Shaman", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=808, place="Thistlefur Village", was=2302}, -- 2306
  {t="C", q=6462, name="Troll Charm", z=331, x=39.69, y=32.95, note="Below ground", tip="Careful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where Dal Bloodclaw roams.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=809, place="Thistlefur Hold", was=2303}, -- 2307
  {t="A", q=6482, name="Freedom to Ruul", z=331, x=41.53, y=34.49, target={kind="npc", id=12818, name="Ruul Snowhoof"}, note="Ruul Snowhoof, below ground", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=809, place="Thistlefur Hold", was=2304}, -- 2308
  {t="C", q=6482, name="Freedom to Ruul", z=331, x=39.69, y=32.95, section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=809, place="Thistlefur Hold", was=2305}, -- 2309
  {t="N", text="Je'neu offers a Blackfathom Deeps quest next; leave it unless you have a group.", tip="Back west to Zoram'gar from Thistlefur before heading east for good.", section="Ashenvale & Thousand Needles (27-29)", p=810, place="Zoram'gar Outpost"}, -- 2310
