  {t="A", q=6544, name="Torek's Assault", z=331, x=68.34, y=75.3, target={kind="npc", id=12858, name="Torek"}, tip="Keep east on the road. Torek waits south-west of the Warsong lumber camp. He and his grunts storm the Silverwing Outpost: let them take aggro and stay with Torek until Duriel Moonfire is dead.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=814, place="Torek's Assault", was=2316}, -- 2320
  {t="C", q=6544, name="Torek's Assault", z=331, x=68.34, y=75.3, section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=814, place="Torek's Assault", was=2317}, -- 2321
  {t="A", q=6503, name="Ashenvale Outrunners", z=331, x=71.11, y=68.12, target={kind="npc", id=12867, name="Kuray'bin"}, note="Kuray'bin", tip="From the Silverwing Outpost head north-east to the Warsong lumber camp on the road: Kuray'bin stands there.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=815, place="Warsong lumber camp", was=2318}, -- 2322
  {t="C", q=6503, name="Ashenvale Outrunners", gv="Kill", gw="Ashenvale Outrunner", z=331, x=72.5, y=69.5, note="Kill Ashenvale Outrunner", tip="The night elf Ashenvale Outrunners (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=816, place="Ashenvale Outrunners"}, -- 2323
  {t="T", q=6503, name="Ashenvale Outrunners", z=331, x=71.11, y=68.12, target={kind="npc", id=12867, name="Kuray'bin"}, note="Kuray'bin", tip="Back to Kuray'bin at the lumber camp, on the road north to Splintertree.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=817, place="Warsong lumber camp"}, -- 2324
