  {t="T", q=6383, name="The Ashenvale Hunt", z=331, x=73.78, y=61.46, target={kind="npc", id=12696, name="Senani Thunderheart"}, tip="Senani Thunderheart keeps the hunt board at Night Run, by the flight master: take The Ashenvale Hunt and hand it straight back. Ursangous, Sharptalon and Shadumbra drop their trophies only after it.", notTurnedIn={6383}, direct=true, section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=819, place="Senani Thunderheart", was=2323}, -- 2327
