  {t="C", q=1195, name="The Sacred Flame", gv="Collect", gw="Filled Etched Phial", z=331, x=60.2, y=72.91, note="Collect Filled Etched Phial", onQuest={1195}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Ashenvale", p=825, place="Ashenvale Moonwell", was=2335}, -- 2339
