  {t="G", text="Zoram'gar Outpost flight master", z=1638, x=12.2, y=33.8, tip="Fly to Thunder Bluff from Zoram'gar. If you don't know its flight path, fly to Camp Taurajo and walk north through Mulgore instead.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thunder Bluff", p=838, place="Fly to Thunder Bluff"}, -- 2360
  {t="F", text="Thunder Bluff", section="Ashenvale & Thousand Needles (27-29)", p=838, place="Fly to Thunder Bluff"}, -- 2361
  {t="G", text="North of Thunder Bluff", z=215, x=40.9, y=31.69, tip="The Earthen Ring camp and its three quests stand up on Skywatcher Plateau, north of Thunder Bluff. Fly to Thunder Bluff if you know its flight path and take a lift down, else fly to Camp Taurajo and walk north through Mulgore; the arrow then leads round to the plateau's north end and up onto it.", races={"orc", "troll", "undead"}, classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock", "Druid"}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Mulgore", p=839, place="Skywatcher Plateau"}, -- 2362
  {t="G", text="Skywatcher Plateau", z=215, x=32.47, y=20.0, races={"orc", "troll", "undead"}, classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock", "Druid"}, section="Ashenvale & Thousand Needles (27-29)", zoneName="Mulgore", p=840, place="Skywatcher Plateau"}, -- 2363
  {t="A", q=96260, name="Stronger than Steel", foreverOnly=true, z=215, x=32.47, y=19.98, target={kind="npc", id=264072, name="Yorn Grimtotem"}, note="Yorn Grimtotem", tip="The Earthen Ring camp stands north of the bluffs: Mazu'kon, Yorn Grimtotem and Muln Earthfury. From Thunder Bluff, take a lift down; coming on foot from Camp Taurajo, keep north past the bluffs.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Mulgore", p=841, place="The Earthen Ring", was=2360}, -- 2364
  {t="A", q=96241, name="Talkin' bout Toxins, Mon", foreverOnly=true, z=215, x=32.5, y=20.6, target={kind="npc", id=264074, name="Mazu'kon"}, note="Mazu'kon", section="Ashenvale & Thousand Needles (27-29)", zoneName="Mulgore", p=841, place="The Earthen Ring", was=2361}, -- 2365
  {t="A", q=96259, name="Defending the Dead", foreverOnly=true, z=215, x=33.41, y=22.59, target={kind="npc", id=259118, name="Muln Earthfury"}, note="Muln Earthfury: The Broodmother comes once this is handed in", section="Ashenvale & Thousand Needles (27-29)", zoneName="Mulgore", p=841, place="The Earthen Ring", was=2362}, -- 2366
  {t="C", q=96260, obj=1, name="Stronger than Steel", foreverOnly=true, z=215, x=33.13, y=15.75, note="Crystalline Silk, from Gloomrise Spinners", tip="North of the camp, spiders overrun the burial ground at Gloomrise. Use Mazu'kon's Toxin Extractor on the Gnawed Corpses; the Spinners drop the Crystalline Silk. Broodmother Valraxx (30, elite) sits at the north end: leave her unless you do The Broodmother with a group; her Bloody Parchment starts A Darker Truth.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Mulgore", p=842, place="Gloomrise: kill these as you meet them", was=2363}, -- 2367
