  {t="T", q=5881, name="Calling in the Reserves", z=400, x=31.86, y=21.66, target={kind="npc", id=12576, name="Grish Longrunner"}, note="Grish Longrunner", tip="Grish Longrunner and Brave Moonhorn wait at the top of the Great Lift: Maggran's letter is for Grish, and Moonhorn's message goes down to Freewind Post with you.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=856, place="The Great Lift", was=2389}, -- 2393
  {t="A", q=4542, name="Message to Freewind Post", z=400, x=32.24, y=22.17, target={kind="npc", id=10079, name="Brave Moonhorn"}, note="Brave Moonhorn, at the top of the lift: Cliffwatcher Longhorn at Freewind Post", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=856, place="The Great Lift", was=2390}, -- 2394
