  {t="C", q=5064, obj=3, name="Grimtotem Spying", z=400, x=39.3, y=41.5, note="Document Chest, south-east camp", tip="West of Freewind, the Grimtotem camps below Darkcloud Pinnacle. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps.", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=866, place="Darkcloud Pinnacle", was=2420}, -- 2424
  {t="C", q=5064, obj=2, name="Grimtotem Spying", z=400, x=33.8, y=40.0, note="Document Chest, south-west camp", section="Ashenvale & Thousand Needles (27-29)", zoneName="Thousand Needles", p=866, place="Darkcloud Pinnacle", was=2421}, -- 2425
