  {t="C", q=528, obj=1, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Peasant", z=267, x=35.41, y=42.01, note="Kill Hillsbrad Peasant", tip="Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping.", notTurnedIn={528}, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=901, place="Hillsbrad Peasants", was=2494}, -- 2498
