  {t="C", q=7321, obj=1, name="Soothing Turtle Bisque", z=267, x=67.8, y=28.0, note="Turtle Meat, from the Snapjaws", tip="South from Tarren Mill along the river: Snapjaws (29) sun themselves on its banks all the way down to the hills above Southshore. Some of them carry Turtle Meat.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=906, place="The river south of Tarren Mill: kill these as you meet them", was=2500}, -- 2506
  {t="C", q=509, name="Elixir of Agony", z=267, x=64.2, y=61.4, note="Mudsnout Blossoms", tip="South of the river's bend, the Mudsnout gnolls (26-28) camp in the hills above Dun Garok; the blossoms grow among their tents. The Shamans heal and call their friends: pull them first.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=907, place="Mudsnout Blossoms", was=2501}, -- 2507
  {t="G", text="North of Southshore", z=267, x=60.0, y=42.0, tip="From the blossoms, back north along the river and then west to Hillsbrad town, well north of Southshore (its guards are 55).", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=908, place="North of Southshore"}, -- 2508
