  {t="C", q=552, name="Helcular's Revenge", gv="Collect", gw="Helcular's Rod", z=267, x=44.5, y=29.4, note="Collect Helcular's Rod", tip="West of Tarren Mill, the Cave and Ferocious Yetis (30-32) fill the Foothill Caverns in the hills; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but they hit hard and come in pairs.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=911, place="Helcular's Rod", was=2513}, -- 2519
  {t="C", q=532, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Councilman", z=267, x=32.06, y=42.43, note="Kill Hillsbrad Councilman", tip="On to Hillsbrad town, south-west of the yeti caves. The town hall is on the town's west side: Magistrate Burnside (30) and Clerk Horrace Whitesteed are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=912, place="Town hall", was=2514}, -- 2520
  {t="C", q=532, obj=3, name="Battle of Hillsbrad", z=267, x=29.73, y=41.75, note="Hillsbrad Proclamation, inside", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=912, place="Town hall", was=2515}, -- 2521
