  {t="C", q=539, obj=2, name="Battle of Hillsbrad", gv="Kill", gw="Hillsbrad Miner", z=267, x=28.3, y=54.8, note="Kill Hillsbrad Miner", tip="Head south-west past Hillsbrad town to the Azurelode Mine. Miners work the tunnels; Foreman Bonds (30) and Miner Hackett (29) are deep inside.", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=915, place="Azurelode Mine", was=2524}, -- 2530
  {t="C", q=567, obj=3, name="Dangerous!", gv="Kill", gw="Miner Hackett", z=267, x=31.8, y=52.7, note="Kill Miner Hackett", section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=915, place="Azurelode Mine", was=2525}, -- 2531
