  {t="A", q=676, name="The Hammer May Fall", z=267, x=61.87, y=19.57, target={kind="npc", id=2770, name="Tallow"}, note="Tallow, outside the inn: the Boulderfist ogres (32-34) on the 38-39 Arathi visit", lvlMin=30.0, section="Hillsbrad Foothills (29-31)", zoneName="Hillsbrad Foothills", p=919, place="Voidglare, Bel'varil and Tallow", was=2538}, -- 2544
  {t="N", text="Keep these in your log: their camps are two to four levels over you now, and the 38-39 guide works them on its first Tarren Mill loop and in Hammerfall.", lvlMin=30.0, section="Hillsbrad Foothills (29-31)", p=919, place="Voidglare, Bel'varil and Tallow"}, -- 2545
