  {t="TR", text="Train at your class trainer", tip="Train while you are in the city.", classes={"Warrior", "Hunter", "Rogue", "Priest", "Shaman", "Mage", "Warlock"}, section="Stranglethorn Vale (33-36)", p=989, place="Orgrimmar trainers"}, -- 2701
  {t="G", text="Orgrimmar flight master", z=17, x=45.3, y=63.7, tip="Booty Bay first: the goblins' boat sails there from Ratchet, and every Booty Bay quest is for the north of the vale, which you then walk up into.", section="Stranglethorn Vale (33-36)", zoneName="The Barrens", p=990, place="Fly to Ratchet"}, -- 2702
  {t="F", text="Ratchet", section="Stranglethorn Vale (33-36)", p=990, place="Fly to Ratchet"}, -- 2703
