  {t="A", q=1180, name="Goblin Sponsorship", z=17, x=62.68, y=36.23, target={kind="npc", id=3391, name="Gazlowe"}, note="Gazlowe: for Wharfmaster Lozgil in Booty Bay, where the boat goes", section="Stranglethorn Vale (33-36)", zoneName="The Barrens", p=991, place="Ratchet", was=2696}, -- 2705
