  {t="T", q=1180, name="Goblin Sponsorship", z=33, x=26.35, y=73.56, target={kind="npc", id=4631, name="Wharfmaster Lozgil"}, note="Wharfmaster Lozgil, on the pier", tip="Wharfmaster Lozgil stands on the pier where the boat docks. Drizzlik's shop is in the building east of the inn; Crank Fizzlebub is on the inn's bottom floor, Baron Revilgaz, Kebok and Krazek upstairs, Gringer the flight master on the upper deck.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=993, place="Booty Bay", was=2700}, -- 2709
  {t="A", q=1181, name="Goblin Sponsorship", z=33, x=26.35, y=73.56, target={kind="npc", id=4631, name="Wharfmaster Lozgil"}, section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=993, place="Booty Bay", was=2701}, -- 2710
