  {t="C", q=187, name="Tiger Mastery", gv="Kill", gw="Elder Stranglethorn Tiger", z=33, x=31.94, y=16.08, note="Kill Elder Stranglethorn Tiger", tip="The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp. Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1000, place="Elder Stranglethorn Tigers", was=2741}, -- 2750
  {t="T", q=187, name="Tiger Mastery", z=33, x=35.62, y=10.62, target={kind="npc", id=717, name="Ajeck Rouack"}, note="Ajeck Rouack", tip="Back north to the camp.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1001, place="Nesingwary's camp", was=2742}, -- 2751
