  {t="A", q=97328, name="Anything of Value", foreverOnly=true, z=33, x=31.5, y=12.85, target={kind="object", id=661516, name="Thoroughly Scavenged Supplies"}, tip="On the walk west from Nesingwary's camp, a pile of Thoroughly Scavenged Supplies lies by the path: it starts Anything of Value, whose Stolen Shipments lie in the Ruins of Zul'Kunda on the coast ahead.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1002, place="Thoroughly Scavenged Supplies", was=2744}, -- 2753
  {t="C", q=605, name="Singing Blue Shards", gv="Collect", gw="Singing Crystal Shard", z=33, x=33.67, y=6.36, note="Collect Singing Crystal Shard", tip="Careful: The raptor nest has young raptors that join the fight when you attack the adults.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1003, place="The Savage Coast: kill these as you meet them", was=2745}, -- 2754
  {t="C", q=189, name="Bloodscalp Ears", gv="Collect", gw="Bloodscalp Ear", z=33, x=31.41, y=11.43, note="Collect Bloodscalp Ear", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1003, place="The Savage Coast: kill these as you meet them", was=2746}, -- 2755
  {t="C", q=194, name="Raptor Mastery", gv="Kill", gw="Stranglethorn Raptor", z=33, x=27.79, y=14.32, note="Kill Stranglethorn Raptor", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1003, place="The Savage Coast: kill these as you meet them", was=2747}, -- 2756
  {t="A", q=97329, name="Where's the Key?", foreverOnly=true, z=33, x=23.46, y=12.79, target={kind="npc", id=268992, name="Zimmix Sputterspark"}, note="Zimmix Sputterspark", tip="Careful: Bloodscalp Berserkers and Headhunters (36-37) and Witch Doctors (37, casters) hold the ruins north and west of Zimmix, close to the northern shipments (around 24.9,9.6): pick the shipments in the southern ruins by Zimmix first, and pull one at a time if you go north.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1004, place="Zimmix Sputterspark", was=2748}, -- 2757
  {t="C", q=97328, obj=1, name="Anything of Value", foreverOnly=true, z=33, x=24.25, y=12.24, note="Stolen Shipments, in the ruins", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1004, place="Zimmix Sputterspark", was=2749}, -- 2758
  {t="C", q=97329, obj=1, name="Where's the Key?", foreverOnly=true, z=33, x=24.46, y=12.32, note="Primitive Key, from the Bloodscalp Scouts, Hunters and Mystics", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1004, place="Zimmix Sputterspark", was=2750}, -- 2759
  {t="T", q=97329, name="Where's the Key?", foreverOnly=true, z=33, x=23.46, y=12.79, target={kind="npc", id=268992, name="Zimmix Sputterspark"}, section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1004, place="Zimmix Sputterspark", was=2751}, -- 2760
