  {t="C", q=195, name="Raptor Mastery", gv="Kill", gw="Lashtail Raptor", z=33, x=32.4, y=23.2, note="Kill Lashtail Raptor", tip="On your way back south to Grom'gol, the Lashtail Raptors (35-36) hunt the jungle between the camp and Grom'gol: they count for Hemet and for Commander Aggro'gosh. Careful: the 36s can be two over you: pull them one at a time. Carnivorous Weeds (36-38) are rooted in the jungle south of the raptors: walk around them.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1006, place="Lashtail Raptors", was=2756}, -- 2766
  {t="C", q=568, name="The Defense of Grom'gol", gv="Kill", gw="Lashtail Raptor", z=33, x=32.4, y=23.17, note="Kill Lashtail Raptor", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1006, place="Lashtail Raptors", was=2757}, -- 2767
  {t="T", q=568, name="The Defense of Grom'gol", z=33, x=32.17, y=28.9, target={kind="npc", id=2464, name="Commander Aggro'gosh"}, note="Commander Aggro'gosh", tip="Commander Aggro'gosh stands in the middle of Grom'gol, Nimboya near the zeppelin tower, Far Seer Mok'thardin beside the flight master.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1007, place="Grom'gol", was=2758}, -- 2768
  {t="A", q=569, name="The Defense of Grom'gol", z=33, x=32.17, y=28.9, target={kind="npc", id=2464, name="Commander Aggro'gosh"}, section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1007, place="Grom'gol", was=2759}, -- 2769
