  {t="T", q=575, name="Supply and Demand", z=33, x=28.29, y=77.59, target={kind="npc", id=2495, name="Drizzlik"}, note="Drizzlik, inside", tip="Drizzlik's shop is in the building east of the inn; Crank Fizzlebub is on the inn's bottom floor, Baron Revilgaz, Kebok and Krazek upstairs beside the flight master. Wharfmaster Lozgil stands on the pier.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1009, place="Booty Bay", was=2765}, -- 2775
