  {t="T", q=596, name="Bloody Bone Necklaces", z=33, x=32.27, y=27.71, target={kind="npc", id=2519, name="Kin'weelay"}, note="Kin'weelay", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1014, place="Grom'gol", was=2781}, -- 2791
  {t="T", q=629, name="The Vile Reef", z=33, x=32.27, y=27.71, target={kind="npc", id=2519, name="Kin'weelay"}, note="Kin'weelay", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1014, place="Grom'gol", was=2782}, -- 2792
