  {t="C", q=569, obj=1, name="The Defense of Grom'gol", gv="Kill", gw="Mosh'Ogg Brute", z=33, x=37.89, y=30.24, note="Kill Mosh'Ogg Brute", tip="The Mosh'Ogg ogres camp in the hills just east of Grom'gol, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time. Careful: the 37s can be two over you: take them from the camp's western edge, never two together.", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1016, place="Mosh'Ogg camp", was=2788}, -- 2798
  {t="C", q=569, obj=2, name="The Defense of Grom'gol", gv="Kill", gw="Mosh'Ogg Witch Doctor", z=33, x=38.16, y=30.05, note="Kill Mosh'Ogg Witch Doctor", section="Stranglethorn Vale (33-36)", zoneName="Stranglethorn Vale", p=1016, place="Mosh'Ogg camp", was=2789}, -- 2799
