  {t="T", q=1719, name="The Affray", z=17, x=68.62, y=49.16, target={kind="npc", id=6236, name="Klannoc Macleod"}, note="Klannoc Macleod: Berserker Stance", classes={"Warrior"}, section="Dustwallow Marsh & Desolace (36-38)", zoneName="The Barrens", p=1041, place="The Affray", was=2858}, -- 2868
  {t="G", text="Ratchet flight master", z=17, x=63.1, y=37.1, tip="Back north along the coast to Ratchet's flight master.", classes={"Warrior"}, section="Dustwallow Marsh & Desolace (36-38)", zoneName="The Barrens", p=1042, place="Ratchet flight master"}, -- 2869
  {t="F", text="Shadowprey Village", tip="Fly to Shadowprey Village from the flight master you are next to: Ratchet's, or Brackenwall's if you had no errand in Ratchet.", section="Dustwallow Marsh & Desolace (36-38)", p=1043, place="Fly to Shadowprey Village"}, -- 2870
  {t="A", q=5381, name="Hand of Iruxos", z=405, x=25.82, y=68.21, target={kind="npc", id=11624, name="Taiga Wisemane"}, note="Taiga Wisemane: the Hand of Iruxos, at Thunder Axe Fortress later on this visit", tip="Taiga Wisemane and Drulzegar Skraghook stand in the village.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1044, place="Shadowprey Village", was=2861}, -- 2871
  {t="A", q=6143, name="Other Fish to Fry", z=405, x=23.32, y=72.87, target={kind="npc", id=12340, name="Drulzegar Skraghook"}, note="Drulzegar Skraghook: the Slitherblade of Sar'theris Strand, on the way back from Thunder Axe Fortress", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1044, place="Shadowprey Village", was=2862}, -- 2872
  {t="A", q=93225, name="Carved Centaur Totems", foreverOnly=true, z=405, x=56.29, y=59.68, target={kind="npc", id=5412, name="Gurda Wildmane"}, note="Gurda Wildmane", tip="East along the road to Ghost Walker Post; Gurda Wildmane stands beside Felgur Twocuts.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1045, place="Ghost Walker Post", was=2863}, -- 2873
  {t="A", q=1366, name="Centaur Bounty", z=405, x=56.19, y=59.57, target={kind="npc", id=5395, name="Felgur Twocuts"}, note="Felgur Twocuts: his Centaur Bounty, from the same Maraudine as Gurda's totems", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1045, place="Ghost Walker Post", was=2864}, -- 2874
  {t="C", q=93225, obj=1, name="Carved Centaur Totems", gv="Collect", gw="5 Carved Centaur Totem", foreverOnly=true, z=405, x=33.0, y=54.0, note="Collect 5 Carved Centaur Totem", tip="Careful: Khan Hratha and the Rock Worms (41-42, elite) hold the valley's north-western end with the Khan Guards and Marauders (39-40), and the Magram's village in the south-east has Necromancers (42-43): keep east of the arrow.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1046, place="Valley of Spears", was=2865}, -- 2875
  {t="C", q=1366, name="Centaur Bounty", gv="Collect", gw="Centaur Ear", z=405, x=68.55, y=52.17, note="Collect Centaur Ear", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1046, place="Valley of Spears", was=2866}, -- 2876
  {t="A", q=6132, name="Get Me Out of Here!", z=405, x=33.95, y=53.5, target={kind="npc", id=12277, name="Melizza Brimbuzzle"}, tip="Careful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1047, place="Melizza Brimbuzzle", was=2867}, -- 2877
  {t="C", q=6132, name="Get Me Out of Here!", z=405, x=33.95, y=53.5, section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1047, place="Melizza Brimbuzzle", was=2868}, -- 2878
  {t="T", q=6132, name="Get Me Out of Here!", z=405, x=47.83, y=61.83, target={kind="npc", id=6019, name="Hornizz Brimbuzzle"}, tip="Hornizz waits at the goblin camp on the west side of the Kodo Graveyard.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1048, place="Hornizz Brimbuzzle", was=2869}, -- 2879
  {t="A", q=6134, name="Ghost-o-plasm Round Up", z=405, x=47.83, y=61.83, target={kind="npc", id=6019, name="Hornizz Brimbuzzle"}, note="Hornizz Brimbuzzle: the ghost-o-plasm, after Mannoroc Coven at the end of this visit", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1048, place="Hornizz Brimbuzzle", was=2870}, -- 2880
  {t="T", q=93225, name="Carved Centaur Totems", foreverOnly=true, z=405, x=56.29, y=59.68, target={kind="npc", id=5412, name="Gurda Wildmane"}, note="Gurda Wildmane", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1049, place="Ghost Walker Post", was=2871}, -- 2881
  {t="T", q=1366, name="Centaur Bounty", z=405, x=56.19, y=59.57, target={kind="npc", id=5395, name="Felgur Twocuts"}, note="Felgur Twocuts", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1049, place="Ghost Walker Post", was=2872}, -- 2882
  {t="C", q=5381, obj=1, name="Hand of Iruxos", z=405, x=55.0, y=26.7, note="Demon Pick, on the Hand of Iruxos Crystal", tip="North up the road to Thunder Axe Fortress. Clear the middle of the largest building, then use the Demon Pick on the red Hand of Iruxos Crystal there. A Demon Spirit (37) comes out: kill it for the Demon Box. The Burning Blade around it are well under you now.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1050, place="Thunder Axe Fortress", was=2873}, -- 2883
  {t="C", q=5381, name="Hand of Iruxos", gv="Collect", gw="Demon Box", z=405, x=55, y=26.6, note="Collect Demon Box", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1050, place="Thunder Axe Fortress", was=2874}, -- 2884
  {t="C", q=6143, obj=1, name="Other Fish to Fry", gv="Kill", gw="Slitherblade Myrmidon", z=405, x=33.75, y=22.38, note="Kill Slitherblade Myrmidon", tip="West from the fortress to the coast at Sar'theris Strand: the Slitherblade Myrmidons, Naga and Sorceresses hold the beach. Pull them one at a time; the Sea Witches and Oracles (34-36) cast from range.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1051, place="Sar'theris Strand", was=2875}, -- 2885
  {t="C", q=6143, obj=2, name="Other Fish to Fry", gv="Kill", gw="Slitherblade Naga", z=405, x=35.4, y=22.01, note="Kill Slitherblade Naga", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1051, place="Sar'theris Strand", was=2876}, -- 2886
  {t="C", q=6143, obj=3, name="Other Fish to Fry", gv="Kill", gw="Slitherblade Sorceress", z=405, x=32.94, y=23.32, note="Kill Slitherblade Sorceress", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1051, place="Sar'theris Strand", was=2877}, -- 2887
  {t="T", q=5381, name="Hand of Iruxos", z=405, x=25.82, y=68.21, target={kind="npc", id=11624, name="Taiga Wisemane"}, note="Taiga Wisemane", tip="South down the coast to Shadowprey: Taiga takes the box and sends you to Mannoroc Coven with it; Drulzegar takes the naga.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1052, place="Shadowprey Village", was=2878}, -- 2888
  {t="A", q=5581, name="Portals of the Legion", z=405, x=25.82, y=68.21, target={kind="npc", id=11624, name="Taiga Wisemane"}, section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1052, place="Shadowprey Village", was=2879}, -- 2889
  {t="T", q=6143, name="Other Fish to Fry", z=405, x=23.32, y=72.87, target={kind="npc", id=12340, name="Drulzegar Skraghook"}, note="Drulzegar Skraghook", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1052, place="Shadowprey Village", was=2880}, -- 2890
  {t="G", text="Mannoroc Coven", z=405, x=52.0, y=78.0, tip="Head east to Mannoroc Coven. With the Hand of Iruxos from Taiga in your bags, open a demon portal's ring: a Demon Portal Guardian (38-39) comes out; kill it to close that portal. Six portals. Careful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1053, place="Portals of the Legion"}, -- 2891
  {t="C", q=5581, name="Portals of the Legion", z=405, x=52.6, y=77.4, section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1053, place="Portals of the Legion", was=2882}, -- 2892
  {t="C", q=6134, obj=1, name="Ghost-o-plasm Round Up", gv="Use", gw="Crate of Ghost Magnets", z=405, x=64.4, y=91.7, note="Use the Crate of Ghost Magnets", tip="Careful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields just west of the arrow, well above you: use the crate at the arrow, on the valley's eastern side, and pull the spectres away from them.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1054, place="The Valley of Bones", was=2883}, -- 2893
  {t="C", q=6134, name="Ghost-o-plasm Round Up", z=405, x=64.4, y=91.7, note="Ghost-o-plasm", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1054, place="The Valley of Bones", was=2884}, -- 2894
  {t="T", q=6134, name="Ghost-o-plasm Round Up", z=405, x=47.83, y=61.83, target={kind="npc", id=6019, name="Hornizz Brimbuzzle"}, tip="North-west to the goblin camp on the west side of the Kodo Graveyard, back past Mannoroc Coven: keep west of the Magram's village.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1055, place="Hornizz Brimbuzzle", was=2885}, -- 2895
  {t="T", q=5581, name="Portals of the Legion", z=405, x=25.82, y=68.21, target={kind="npc", id=11624, name="Taiga Wisemane"}, note="Taiga Wisemane", tip="Hearth to Shadowprey: your hearthstone is still bound there.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Desolace", p=1056, place="Shadowprey", was=2886}, -- 2896
  {t="F", text="Thunder Bluff", tip="Fly from Shadowprey Village to Thunder Bluff and train with Turak Runetotem on Elder Rise; fly on to Orgrimmar from there.", classes={"Druid"}, section="Dustwallow Marsh & Desolace (36-38)", p=1057, place="Thunder Bluff"}, -- 2897
  {t="TR", text="Train at your class trainer", classes={"Druid"}, section="Dustwallow Marsh & Desolace (36-38)", p=1057, place="Thunder Bluff"}, -- 2898
