  {t="T", q=1184, name="Parts of the Swarm", z=1637, x=75.23, y=34.24, target={kind="npc", id=4485, name="Belgrom Rockmaul"}, note="Belgrom Rockmaul", tip="Belgrom Rockmaul stands in the Valley of Honor.", section="Dustwallow Marsh & Desolace (36-38)", zoneName="Orgrimmar", p=1060, place="Belgrom Rockmaul", was=2893}, -- 2903
  {t="T", q=2841, name="Rig Wars", z=1637, x=75.99, y=25.41, target={kind="npc", id=3412, name="Nogg"}, note="Nogg", tip="Nogg's workshop is in the Valley of Honor beside Belgrom: hand in Rig Wars if you ran Gnomeregan.", ready=2841, section="Dustwallow Marsh & Desolace (36-38)", zoneName="Orgrimmar", p=1061, place="Nogg", was=2894}, -- 2904
  {t="TR", text="Train at your class trainer", tip="Train while you are in the city; everyone else trains in the Undercity, next.", classes={"Hunter", "Shaman"}, section="Dustwallow Marsh & Desolace (36-38)", p=1062, place="Orgrimmar trainers"}, -- 2905
  {t="N", text="The next guide takes the Undercity zeppelin from the tower outside the main gate.", classes={"Hunter", "Shaman"}, section="Dustwallow Marsh & Desolace (36-38)", p=1062, place="Orgrimmar trainers"}, -- 2906
  {t="G", text="Zeppelin to Undercity", z=14, x=50.8, y=13.5, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Durotar", p=1063, place="Zeppelin to Undercity"}, -- 2907
  {t="TR", text="Train at your class trainer", tip="Train while you are in the Undercity: the trainers stand in the War Quarter, the Rogues' Quarter and the Magic Quarter (Paladins: Garen Largo).", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Alterac Mountains & Arathi Highlands (37-39)", p=1064, place="Undercity trainers"}, -- 2908
  {t="T", q=97985, name="Thundering Hearts", foreverOnly=true, z=1497, x=49.11, y=70.14, target={kind="npc", id=270038, name="Calder Gray"}, note="Calder Gray: Stormheart's heart from Thousand Needles", tip="Calder Gray stands in the Apothecarium.", onQuest={97985}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Undercity", p=1065, place="Calder Gray", was=2899}, -- 2909
