  {t="A", q=544, name="Prison Break In", z=267, x=61.6, y=20.85, target={kind="npc", id=2410, name="Magus Wordeen Voidglare"}, note="Magus Wordeen Voidglare, inside", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1067, place="Tarren Mill", was=2903}, -- 2913
