  {t="A", q=556, name="Stone Tokens", z=267, x=61.5, y=20.93, target={kind="npc", id=2437, name="Keeper Bel'varil"}, note="Keeper Bel'varil, inside", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1067, place="Tarren Mill", was=2905}, -- 2915
  {t="A", q=676, name="The Hammer May Fall", z=267, x=61.87, y=19.57, target={kind="npc", id=2770, name="Tallow"}, note="Tallow: for Drum Fel in Hammerfall, later in this guide", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1067, place="Tarren Mill", was=2906}, -- 2916
  {t="N", text="Buy 1 Southshore Stout", note="Southshore Stout, for Henchman Valik", section="Alterac Mountains & Arathi Highlands (37-39)", p=1067, place="Tarren Mill"}, -- 2917
  {t="SH", text="Tarren Mill", z=267, x=62.78, y=19.03, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1067, place="Tarren Mill"}, -- 2918
  {t="A", q=535, name="Valik", z=36, x=57.17, y=69.51, target={kind="npc", id=2333, name="Henchman Valik"}, tip="Follow the road north out of Tarren Mill into the Alterac foothills: Valik waits by the Syndicate camp. He offers his errand only while you carry Krusk's Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes Valik.", notReady=533, onQuest={533}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1068, place="Henchman Valik", was=2909}, -- 2919
  {t="T", q=535, name="Valik", z=36, x=57.17, y=69.51, target={kind="npc", id=2333, name="Henchman Valik"}, notReady=533, onQuest={533}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1068, place="Henchman Valik", was=2910}, -- 2920
  {t="C", q=533, name="Infiltration", gv="Collect", gw="Syndicate Missive", z=36, x=57.6, y=68.54, note="Collect Syndicate Missive", tip="Only if Valik's missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1069, place="Syndicate missives", was=2911}, -- 2921
  {t="G", text="South of the Dalaran crater's camp", z=36, x=22.0, y=93.5, tip="West along the foot of the hills, south of the road: a Kirin Tor Guard (55) walks that road from the north-east down into the traitors' camp.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1070, place="Alterac Mountains"}, -- 2922
  {t="C", q=544, obj=1, name="Prison Break In", z=36, x=19.91, y=85.97, note="Dermot", tip="Careful: Kirin Tor Guards (55) attack the Horde on sight, and one of them patrols the road that comes down into the camp from the north-east and walks right up to the traitors: he has killed many players here. Watch for him, let him walk back up the road, then pull the traitors. Many of the camp's guards stand in linked pairs and others patrol alone. Arcane Sentries (55, elite) and Kirin Tor Enforcers (55) stand around the violet dome itself: keep to the camp below the rim.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1071, place="The Dalaran crater", was=2913}, -- 2923
  {t="C", q=544, obj=2, name="Prison Break In", z=36, x=20.16, y=84.28, note="Ricter", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1071, place="The Dalaran crater", was=2914}, -- 2924
  {t="C", q=544, obj=3, name="Prison Break In", z=36, x=20.34, y=86.4, note="Alina", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1071, place="The Dalaran crater", was=2915}, -- 2925
  {t="C", q=544, obj=4, name="Prison Break In", z=36, x=17.8, y=83.2, note="Kegan Darkmar", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1071, place="The Dalaran crater", was=2916}, -- 2926
