  {t="T", q=533, name="Infiltration", z=267, x=63.24, y=20.66, target={kind="npc", id=2229, name="Krusk"}, note="Krusk, inside", tip="Back east along the foothills to Tarren Mill: everything from the first loop is handed in inside the inn.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Hillsbrad Foothills", p=1073, place="Tarren Mill", was=2920}, -- 2930
