  {t="C", q=545, obj=2, name="Dalaran Patrols", gv="Kill", gw="Elemental Slave", z=36, x=22.4, y=58.6, note="Kill Elemental Slave", tip="From Strahnbrad follow the road south-west to Gallows' Corner and on west to the ruins north of the Dalaran crater, along the lake shore. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves. Careful: Arcane Sentries (55, elite) and Kirin Tor Guards (55) guard the dome itself and attack the Horde: work the ruins' outer edge and don't go up to the dome.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1076, place="Old Dalaran Ruins: kill these as you meet them", was=2933}, -- 2943
  {t="C", q=557, obj=1, name="Bracers of Binding", gv="Collect", gw="Bracers of Earth Binding", z=36, x=21.6, y=61.9, note="Collect Bracers of Earth Binding", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Alterac Mountains", p=1076, place="Old Dalaran Ruins: kill these as you meet them", was=2934}, -- 2944
