  {t="A", q=97539, name="Silky Sutures", foreverOnly=true, z=45, x=73.41, y=36.89, target={kind="npc", id=12920, name="Doctor Gregory Victor"}, note="Doctor Gregory Victor, at the south gate. If Doctor Gregory Victor offers nothing, another player may be running his First Aid quest Triage: he can be busy for a few minutes. Wait, then talk to him again.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1082, place="Hammerfall", was=2954}, -- 2964
  {t="A", q=639, name="Sigil of Strom", group=true, z=45, x=73.8, y=33.96, target={kind="npc", id=2703, name="Zengu"}, note="Zengu", tip="Zengu's Sigil of Strom drops from the elite Syndicate (35-38) in Stromgarde's ruins, the west of the highlands. Great XP if you have a group for it: the route passes Stromgarde on its way to the inner circle.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1083, place="Stromgarde quests for a group", was=2955}, -- 2965
  {t="C", q=642, name="The Princess Trapped", gv="Collect", gw="Mote of Myzrael", z=45, x=77.49, y=34.88, note="Collect Mote of Myzrael", tip="Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1084, place="Drywhisker Gorge", was=2956}, -- 2966
