  {t="C", q=651, name="Stones of Binding", z=45, x=66.7, y=29.72, note="Cresting Key", tip="Careful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1086, place="The Stone of East Binding", was=2959}, -- 2969
  {t="C", q=677, obj=2, name="Call to Arms", gv="Kill", gw="Witherbark Headhunter", z=45, x=74.16, y=45.89, note="Kill Witherbark Headhunter", tip="South of Hammerfall, the Witherbark trolls hold the village in the hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village. Careful: All three troll types flee for help at 15% health, which can pull more trolls from the nearby camps.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1087, place="Witherbark Village", was=2960}, -- 2970
  {t="C", q=677, obj=1, name="Call to Arms", gv="Kill", gw="Witherbark Axe Thrower", z=45, x=70.71, y=58.83, note="Kill Witherbark Axe Thrower", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1087, place="Witherbark Village", was=2961}, -- 2971
