  {t="A", q=665, name="Sunken Treasure", z=45, x=33.87, y=80.55, target={kind="npc", id=2768, name="Professor Phizzlethorpe"}, note="Professor Phizzlethorpe", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1099, place="Faldir's Cove", was=3001}, -- 3011
  {t="G", text="Professor Phizzlethorpe", z=45, x=33.9, y=80.6, tip="Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1100, place="Professor Phizzlethorpe"}, -- 3012
  {t="C", q=665, name="Sunken Treasure", z=45, x=33.9, y=80.6, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1100, place="Professor Phizzlethorpe", was=3003}, -- 3013
  {t="T", q=665, name="Sunken Treasure", z=45, x=33.86, y=80.45, target={kind="npc", id=2774, name="Doctor Draxlegauge"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1101, place="Doctor Draxlegauge", was=3004}, -- 3014
  {t="A", q=666, name="Sunken Treasure", z=45, x=33.86, y=80.45, target={kind="npc", id=2774, name="Doctor Draxlegauge"}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1101, place="Doctor Draxlegauge", was=3005}, -- 3015
  {t="C", q=664, obj=1, name="Drowned Sorrows", z=45, x=25.42, y=85.23, note="Underwater", tip="West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks.", section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1102, place="The Drowned Reef: kill these as you meet them", was=3006}, -- 3016
