  {t="N", text="The next guide crosses the Thandol Span into the Wetlands and heads for the Badlands.", section="Alterac Mountains & Arathi Highlands (37-39)", p=1103, place="Faldir's Cove"}, -- 3029
  {t="T", q=639, name="Sigil of Strom", z=45, x=73.8, y=33.96, target={kind="npc", id=2703, name="Zengu"}, note="Zengu", tip="Only if you ran Stromgarde with a group: back to Hammerfall for its hand-ins, then on to the Thandol Span.", onQuest={639, 679, 680}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1104, place="Back to Hammerfall", was=3020}, -- 3030
  {t="T", q=679, name="Call to Arms", z=45, x=74.24, y=33.92, target={kind="npc", id=2771, name="Drum Fel"}, note="Drum Fel", onQuest={639, 679, 680}, section="Alterac Mountains & Arathi Highlands (37-39)", zoneName="Arathi Highlands", p=1104, place="Back to Hammerfall", was=3021}, -- 3031
