  {t="G", text="Valley of Fangs", z=3, x=42.3, y=52.8, tip="Head for the Thandol Span, the great bridge at Arathi's southern edge, cross it and follow the road south through the Wetlands to the Dun Algaz tunnel into Loch Modan. Thelsamar, the dwarf town on the road in the middle of Loch Modan, has guards who attack the Horde: leave the road before it and pass the town on the hills to its west. The road leaves Loch Modan to the south into the Badlands; follow it to the goblin camp in the Valley of Fangs.", section="Badlands (38-39)", zoneName="Badlands", p=1105, place="Into the Badlands"}, -- 3033
  {t="T", q=1106, name="Martek the Exiled", z=3, x=42.22, y=52.69, target={kind="npc", id=4618, name="Martek the Exiled"}, note="Martek the Exiled: Fizzle's letter from the Shimmering Flats", section="Badlands (38-39)", zoneName="Badlands", p=1106, place="Valley of Fangs", was=3024}, -- 3034
  {t="A", q=1108, name="Indurium", z=3, x=42.22, y=52.69, target={kind="npc", id=4618, name="Martek the Exiled"}, section="Badlands (38-39)", zoneName="Badlands", p=1106, place="Valley of Fangs", was=3025}, -- 3035
  {t="A", q=703, name="Barbecued Buzzard Wings", z=3, x=42.39, y=52.93, target={kind="npc", id=2817, name="Rigglefuzz"}, note="Rigglefuzz", section="Badlands (38-39)", zoneName="Badlands", p=1106, place="Valley of Fangs", was=3026}, -- 3036
  {t="A", q=710, name="Study of the Elements: Rock", z=3, x=25.95, y=44.87, target={kind="npc", id=2921, name="Lotwil Veriatus"}, note="Lotwil Veriatus", tip="Head west along the road towards Kargath; Lotwil's camp sits in the Dustbowl halfway there.", section="Badlands (38-39)", zoneName="Badlands", p=1107, place="The Dustbowl", was=3027}, -- 3037
  {t="FP", text="Kargath flight path", tip="Kargath is the Horde fortress built into the cliffs at the zone's western edge. Neeka Bloodscar stands on Kargath's upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart.", section="Badlands (38-39)", p=1108, place="Kargath"}, -- 3038
  {t="A", q=1419, name="Coyote Thieves", z=3, x=6.49, y=47.2, target={kind="npc", id=5394, name="Neeka Bloodscar"}, note="Neeka Bloodscar", section="Badlands (38-39)", zoneName="Badlands", p=1108, place="Kargath", was=3029}, -- 3039
  {t="A", q=1420, name="Report to Helgrum", z=3, x=6.49, y=47.2, target={kind="npc", id=5394, name="Neeka Bloodscar"}, note="for Helgrum in Stonard, around level 42", section="Badlands (38-39)", zoneName="Badlands", p=1108, place="Kargath", was=3030}, -- 3040
