  {t="C", q=710, name="Study of the Elements: Rock", gv="Collect", gw="Small Stone Shard", z=3, x=13.14, y=39.2, note="Collect Small Stone Shard", tip="The small elementals drift across the flats between Kargath and Lotwil's camp, on the road back east. Every rock elemental in the zone can drop Jarkal's Rock Elemental Shards.", section="Badlands (38-39)", zoneName="Badlands", p=1109, place="Lesser Rock Elementals", was=3033}, -- 3043
  {t="C", q=2258, obj=3, name="Badlands Reagent Run", gv="Collect", gw="Rock Elemental Shard", z=3, x=13.14, y=39.2, note="Collect Rock Elemental Shard", section="Badlands (38-39)", zoneName="Badlands", p=1109, place="Lesser Rock Elementals", was=3034}, -- 3044
  {t="T", q=710, name="Study of the Elements: Rock", z=3, x=25.95, y=44.87, target={kind="npc", id=2921, name="Lotwil Veriatus"}, section="Badlands (38-39)", zoneName="Badlands", p=1110, place="Lotwil Veriatus", was=3035}, -- 3045
  {t="A", q=711, name="Study of the Elements: Rock", z=3, x=25.95, y=44.87, target={kind="npc", id=2921, name="Lotwil Veriatus"}, section="Badlands (38-39)", zoneName="Badlands", p=1110, place="Lotwil Veriatus", was=3036}, -- 3046
  {t="C", q=1419, name="Coyote Thieves", gv="Collect", gw="Coyote Jawbone", z=3, x=28.25, y=47.6, note="Collect Coyote Jawbone", tip="Careful: the Giant Buzzards are 39-41, and the 41s are two over you at 39: pick the 39s and 40s and pull them one at a time. The Buzzards (37) you kill later for Rigglefuzz's wings drop gizzards too, more rarely.", section="Badlands (38-39)", zoneName="Badlands", p=1111, place="Badlands: kill these as you meet them", was=3037}, -- 3047
  {t="C", q=2258, obj=2, name="Badlands Reagent Run", gv="Collect", gw="Crag Coyote Fang", z=3, x=28.25, y=47.6, note="Collect Crag Coyote Fang", section="Badlands (38-39)", zoneName="Badlands", p=1111, place="Badlands: kill these as you meet them", was=3038}, -- 3048
  {t="C", q=2258, obj=1, name="Badlands Reagent Run", gv="Collect", gw="Buzzard Gizzard", z=3, x=17.54, y=49.15, note="Collect Buzzard Gizzard", section="Badlands (38-39)", zoneName="Badlands", p=1111, place="Badlands: kill these as you meet them", was=3039}, -- 3049
  {t="C", q=711, name="Study of the Elements: Rock", gv="Collect", gw="Large Stone Slab", z=3, x=40.4, y=77.1, note="Collect Large Stone Slab", tip="South-east across the basin, the bigger Rock Elementals (39) stand on the slopes west of Agmond's End; each one drops a slab. Every rock elemental can drop Jarkal's Rock Elemental Shards. Careful: Malevolent Mirages (42, elite) drift across these slopes too.", section="Badlands (38-39)", zoneName="Badlands", p=1112, place="Rock Elementals", was=3040}, -- 3050
  {t="C", q=2258, obj=3, name="Badlands Reagent Run", gv="Collect", gw="Rock Elemental Shard", z=3, x=40.51, y=78.29, note="Collect Rock Elemental Shard", section="Badlands (38-39)", zoneName="Badlands", p=1112, place="Rock Elementals", was=3041}, -- 3051
  {t="A", q=709, name="Solution to Doom", group=true, z=3, x=51.39, y=76.87, target={kind="npc", id=2785, name="Theldurin the Lost"}, tip="Theldurin sits among the dwarven ruins at Agmond's End, just east of the elementals. His tablet lies just inside Uldaman's cave mouth, beside level 38 elites: a quest for a group.", section="Badlands (38-39)", zoneName="Badlands", p=1113, place="Agmond's End", was=3042}, -- 3052
  {t="C", q=1108, name="Indurium", gv="Collect", gw="Indurium Flake", z=3, x=51.18, y=71.65, note="Collect Indurium Flake", tip="The Stonevault troggs dig around the cave mouths south of the Valley of Fangs, on the way north from Agmond's End; the Bonesnappers and Shamans drop the flakes. The Buzzards for Rigglefuzz's wings circle the hills between the Valley of Fangs and Agmond's End.", section="Badlands (38-39)", zoneName="Badlands", p=1114, place="Stonevault troggs", was=3043}, -- 3053
  {t="C", q=703, name="Barbecued Buzzard Wings", gv="Collect", gw="Buzzard Wing", z=3, x=50.13, y=77.87, note="Collect Buzzard Wing", section="Badlands (38-39)", zoneName="Badlands", p=1114, place="Stonevault troggs", was=3044}, -- 3054
  {t="T", q=703, name="Barbecued Buzzard Wings", z=3, x=42.39, y=52.93, target={kind="npc", id=2817, name="Rigglefuzz"}, note="Rigglefuzz", tip="The road north to Uldaman runs through the Valley of Fangs: Rigglefuzz and Martek take the wings and the flakes on the way.", section="Badlands (38-39)", zoneName="Badlands", p=1115, place="Valley of Fangs", was=3045}, -- 3055
  {t="T", q=1108, name="Indurium", z=3, x=42.22, y=52.69, target={kind="npc", id=4618, name="Martek the Exiled"}, note="Martek the Exiled", section="Badlands (38-39)", zoneName="Badlands", p=1115, place="Valley of Fangs", was=3046}, -- 3056
  {t="A", q=1137, name="News for Fizzle", z=3, x=42.22, y=52.69, target={kind="npc", id=4618, name="Martek the Exiled"}, note="for Fizzle at the Mirage Raceway, on the way from Freewind Post to Tanaris around level 43", section="Badlands (38-39)", zoneName="Badlands", p=1115, place="Valley of Fangs", was=3047}, -- 3057
  {t="C", q=709, name="Solution to Doom", group=true, z=3, x=39.34, y=18.82, note="Below ground", tip="Keep north on the road to Uldaman's entrance, in the north of the Badlands: the chest lies just inside the cave mouth. Magregan Deepshadow and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together.", section="Badlands (38-39)", zoneName="Badlands", p=1116, place="Ancient Chest", was=3048}, -- 3058
  {t="T", q=709, name="Solution to Doom", group=true, z=3, x=51.39, y=76.87, target={kind="npc", id=2785, name="Theldurin the Lost"}, note="Theldurin the Lost", tip="Head back south down the road, past the Valley of Fangs.", section="Badlands (38-39)", zoneName="Badlands", p=1117, place="Agmond's End", was=3049}, -- 3059
  {t="A", q=728, name="To the Undercity for Yagyin's Digest", group=true, z=3, x=51.39, y=76.87, target={kind="npc", id=2785, name="Theldurin the Lost"}, section="Badlands (38-39)", zoneName="Badlands", p=1117, place="Agmond's End", was=3050}, -- 3060
  {t="T", q=711, name="Study of the Elements: Rock", z=3, x=25.95, y=44.87, target={kind="npc", id=2921, name="Lotwil Veriatus"}, note="Lotwil Veriatus", tip="North-west across the basin to Lotwil's camp. Short of Jarkal's shards? The Lesser Rock Elementals (37) on the flats west of the camp drop them about one kill in five.", section="Badlands (38-39)", zoneName="Badlands", p=1118, place="The Dustbowl", was=3051}, -- 3061
  {t="N", text="Lotwil's next study wants bracers from the Greater Rock Elementals (42-44) in the south-western gulches, well above you: leave it.", section="Badlands (38-39)", p=1118, place="The Dustbowl"}, -- 3062
  {t="C", q=2258, obj=3, name="Badlands Reagent Run", gv="Collect", gw="Rock Elemental Shard", z=3, x=26.01, y=45.78, note="Collect Rock Elemental Shard", section="Badlands (38-39)", zoneName="Badlands", p=1118, place="The Dustbowl", was=3053}, -- 3063
  {t="T", q=1419, name="Coyote Thieves", z=3, x=6.49, y=47.2, target={kind="npc", id=5394, name="Neeka Bloodscar"}, note="Neeka Bloodscar", tip="Head west back to Kargath. Neeka Bloodscar stands on Kargath's upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart.", section="Badlands (38-39)", zoneName="Badlands", p=1119, place="Kargath", was=3054}, -- 3064
  {t="T", q=2258, name="Badlands Reagent Run", z=3, x=2.42, y=46.06, target={kind="npc", id=6868, name="Jarkal Mossmeld"}, note="Jarkal Mossmeld, inside", section="Badlands (38-39)", zoneName="Badlands", p=1119, place="Kargath", was=3055}, -- 3065
  {t="N", text="The next guide flies from Kargath to Grom'gol.", section="Badlands (38-39)", p=1119, place="Kargath"}, -- 3066
  {t="G", text="Kargath flight master", z=1497, x=4.1, y=44.9, tip="Your level 40 training is in the Undercity: fly there from Kargath, train, and take the zeppelin from the towers outside the city to Grom'gol.", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Undercity", p=1120, place="Fly to the Undercity"}, -- 3067
  {t="F", text="Undercity", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Stranglethorn Vale & Swamp of Sorrows (39-41)", p=1120, place="Fly to the Undercity"}, -- 3068
  {t="TR", text="Train at your class trainer", classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Stranglethorn Vale & Swamp of Sorrows (39-41)", p=1121, place="Undercity trainers"}, -- 3069
  {t="TR", text="Train with Velma Warnam", optional=true, z=85, x=60.08, y=52.57, note="Velma Warnam, riding trainer", tip="Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is Velma Warnam in Brill, a short ride north of the zeppelin towers, with Zachariah Post's skeletal horses (20 gold each) beside her. Ride back to the towers for the Grom'gol zeppelin.", races={"undead"}, classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage"}, lvlMin=40.0, section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Tirisfal Glades", p=1122, place="Riding at 40"}, -- 3070
  {t="N", text="Skeletal horses: Zachariah Post, beside Velma Warnam in Brill.", races={"undead"}, classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage"}, lvlMin=40.0, section="Stranglethorn Vale & Swamp of Sorrows (39-41)", p=1122, place="Riding at 40"}, -- 3071
  {t="G", text="Zeppelin to Grom'gol", z=85, x=61.8, y=59.2, classes={"Warrior", "Paladin", "Rogue", "Priest", "Mage", "Warlock"}, section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Tirisfal Glades", p=1123, place="Zeppelin to Grom'gol"}, -- 3072
  {t="G", text="Kargath flight master", z=33, x=4.1, y=44.9, classes={"Hunter", "Shaman", "Druid"}, section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Stranglethorn Vale", p=1124, place="Fly to Grom'gol"}, -- 3073
