  {t="T", q=1240, name="The Troll Witchdoctor", z=33, x=32.27, y=27.71, target={kind="npc", id=2519, name="Kin'weelay"}, note="Kin'weelay", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Stranglethorn Vale", p=1125, place="Grom'gol Base Camp", was=3065}, -- 3075
