  {t="N", text="Sell junk and repair", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", p=1158, place="Booty Bay"}, -- 3158
  {t="N", text="Collect Cortello's Riddle", group=true, tip="The scroll, Cortello's Riddle, lies on the decks of the three ships off the Wild Shore, crewed by pirates of 42-45 who come in pairs, with captains of 45-48: take it with a group. Its chain runs on through the Swamp of Sorrows, Dustwallow Marsh and the Hinterlands.", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", p=1159, place="The Bloodsail ships"}, -- 3159
  {t="A", q=624, name="Cortello's Riddle", group=true, z=33, x=26.92, y=77.35, target={kind="item", id=4056, name="Cortello's Riddle"}, note="for a later stop in the Swamp of Sorrows", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Stranglethorn Vale", p=1159, place="The Bloodsail ships", was=3148}, -- 3160
  {t="G", text="Booty Bay flight master", z=33, x=26.8, y=77.0, tip="Fly back to Grom'gol: Zul'Mamwe's Skullsplitters are just east of it.", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Stranglethorn Vale", p=1160, place="Fly to Grom'gol"}, -- 3161
  {t="F", text="Grom'gol", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", p=1160, place="Fly to Grom'gol"}, -- 3162
  {t="G", text="Skullsplitter warriors", z=33, x=45.06, y=34.07, tip="From Grom'gol head east to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. One pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all. Careful: Ana'thek the Cruel (45) walks the south-western ruins with two guards; Speaking with Gan'zulah's last piece, his Broken Armor, waits for your Stranglethorn stop at about 45.", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Stranglethorn Vale", p=1161, place="Zul'Mamwe"}, -- 3163
  {t="C", q=209, obj=1, name="Skullsplitter Tusks", gv="Collect", gw="Skullsplitter Tusk", z=33, x=45.4, y=36.2, note="Collect Skullsplitter Tusk", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Stranglethorn Vale", p=1161, place="Zul'Mamwe", was=3152}, -- 3164
  {t="C", q=585, obj=3, name="Speaking with Nezzliok", gv="Collect", gw="Zul'Mamwe Trophy", z=33, x=47.65, y=39.54, note="Collect Zul'Mamwe Trophy", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Stranglethorn Vale", p=1161, place="Zul'Mamwe", was=3153}, -- 3165
