  {t="C", q=208, obj=1, name="Big Game Hunter", gv="Collect", gw="Head of Bangalash", group=true, z=33, x=38.2, y=35.6, note="Collect Head of Bangalash", tip="Careful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, King Bangalash calls for help from creatures within 20 yd.", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Stranglethorn Vale", p=1172, place="Big Game Hunter", was=3170}, -- 3182
