  {t="C", q=698, obj=1, name="Lack of Surplus", gv="Collect", gw="Unprepared Sawtooth Flank", z=8, x=53.64, y=55.65, note="Collect Unprepared Sawtooth Flank", tip="The crocolisks wallow in the pools around Galen's camp and south towards Stonard; about one in four drops a flank.", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Swamp of Sorrows", p=1179, place="Sawtooth crocolisks", was=3182}, -- 3194
  {t="N", text="Kill Noboru the Cudgel", z=8, x=54.9, y=34.1, tip="Noboru wanders the clearing south-west of the Fallow Sanctuary; his cudgel starts a quest.", section="Stranglethorn Vale & Swamp of Sorrows (39-41)", zoneName="Swamp of Sorrows", p=1180, place="Noboru the Cudgel"}, -- 3195
