  {t="C", q=95261, obj=2, name="It Takes Guts", foreverOnly=true, note="Rotflesh Mushroom", tip="West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too.", section="Riverglades (41-44)", p=1263, place="Rotflesh Mushrooms", was=3397}, -- 3409
  {t="C", q=95261, obj=1, name="It Takes Guts", foreverOnly=true, z=16591, x=78.7, y=49.8, note="Beast Entrails", tip="South-east back towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. Gul'gash wanders down to this beach too.", hasBelow={268632, 15}, section="Riverglades (41-44)", zoneName="Riverglades", p=1264, place="Finish the Beast Entrails", was=3398}, -- 3410
