  {t="A", q=95267, name="The Monster Surfaces", optional=true, foreverOnly=true, z=16591, x=79.95, y=52.49, target={kind="npc", id=260231, name="Argo Brinewhistle"}, note="The Monster Surfaces: a big beast in the shallows south-west of the port, near Old Rot-Chum, the elite", section="Riverglades (41-44)", zoneName="Riverglades", p=1265, place="Powderfuse Port", was=3402}, -- 3414
  {t="C", q=95267, obj=1, name="The Monster Surfaces", foreverOnly=true, z=16591, x=75.53, y=68.14, note="Sea Monster's Head", tip="The Monstrous Threshadon prowls the shallows south-west of the port, below the murlocs' beaches. Old Rot-Chum, an elite, walks the shore close by: give him room.", onQuest={95267}, section="Riverglades (41-44)", zoneName="Riverglades", p=1266, place="The Monster Surfaces", was=3403}, -- 3415
  {t="T", q=95267, name="The Monster Surfaces", foreverOnly=true, z=16591, x=79.95, y=52.49, target={kind="npc", id=260231, name="Argo Brinewhistle"}, onQuest={95267}, section="Riverglades (41-44)", zoneName="Riverglades", p=1267, place="Argo Brinewhistle", was=3404}, -- 3416
  {t="T", q=95428, name="Clugfist's Decree", foreverOnly=true, z=16591, x=59.37, y=45.6, target={kind="npc", id=256418, name="Krom'rosh"}, note="Krom'rosh: Clugfist's Decree", tip="Back to Rog'mar from the port, where your Hearthstone is set. Krom'rosh in the middle of the fort: Clugfist's word sends him looking for Da'grosh, his warrior in the west.", onQuest={95428}, section="Riverglades (41-44)", zoneName="Riverglades", p=1268, place="Rog'mar", was=3405}, -- 3417
  {t="A", q=94744, name="The Wayward Warrior", foreverOnly=true, z=16591, x=59.37, y=45.6, target={kind="npc", id=256418, name="Krom'rosh"}, note="The Wayward Warrior: for Da'grosh, west of Sunnyglade", onQuest={95428}, section="Riverglades (41-44)", zoneName="Riverglades", p=1268, place="Rog'mar", was=3406}, -- 3418
  {t="T", q=95882, name="WANTED: Scoutmaster Vargas", foreverOnly=true, z=16591, x=60.46, y=47.86, target={kind="npc", id=258031, name="Neza Bloodsnout"}, onQuest={95882}, section="Riverglades (41-44)", zoneName="Riverglades", p=1269, place="Neza Bloodsnout", was=3407}, -- 3419
  {t="T", q=94744, name="The Wayward Warrior", foreverOnly=true, z=16591, x=33.47, y=37.93, target={kind="npc", id=258570, name="Da'grosh"}, note="Da'grosh", tip="West from Rog'mar through Sunnyglade and on up the valley towards Twilight's Shroud: Da'grosh, Krom'rosh's wayward warrior, keeps a camp in the hills below the Twilight cult's fortress.", onQuest={94744}, section="Riverglades (41-44)", zoneName="Riverglades", p=1270, place="Da'grosh", was=3408}, -- 3420
