  {t="A", q=95432, name="Rise Up!", foreverOnly=true, z=16591, x=27.66, y=36.54, target={kind="npc", id=260993, name="Crag'rog"}, note="Rise Up!", onQuest={95431}, section="Riverglades (41-44)", zoneName="Riverglades", p=1271, place="Crag'rog", was=3413}, -- 3425
  {t="C", q=94745, obj=1, name="Carving a Path", foreverOnly=true, z=16591, x=27.79, y=36.89, note="Twilight Fanatic", tip="The cult's camps fill the valley south and west of Da'grosh. Free the captive Rog'mar Scouts as you find them. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. Overlord Kilgar and Executioner Morg (elites, 46) hold the fortress at the valley's head: pull the cultists away from them. Sergeant Riftan's Alliance camp sits at the valley's south end, and its Farholde Lookouts (level 46) attack the Horde: stay north of it.", onQuest={94745, 94748}, section="Riverglades (41-44)", zoneName="Riverglades", p=1272, place="The Twilight camps", was=3414}, -- 3426
  {t="C", q=94745, obj=2, name="Carving a Path", foreverOnly=true, z=16591, x=27.73, y=37.17, note="Twilight Corrupter", onQuest={94745, 94748}, section="Riverglades (41-44)", zoneName="Riverglades", p=1272, place="The Twilight camps", was=3415}, -- 3427
  {t="C", q=94745, obj=3, name="Carving a Path", foreverOnly=true, z=16591, x=27.92, y=37.16, note="Twilight Champion", onQuest={94745, 94748}, section="Riverglades (41-44)", zoneName="Riverglades", p=1272, place="The Twilight camps", was=3416}, -- 3428
