  {t="C", q=95432, name="Rise Up!", foreverOnly=true, z=16591, x=26.9, y=34.9, note="recruit five Ogre Miners", tip="Careful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in.", onQuest={95432}, section="Riverglades (41-44)", zoneName="Riverglades", p=1273, place="The ogre mine", was=3418}, -- 3430
  {t="T", q=95432, name="Rise Up!", foreverOnly=true, z=16591, x=27.66, y=36.54, target={kind="npc", id=260993, name="Crag'rog"}, onQuest={95432}, section="Riverglades (41-44)", zoneName="Riverglades", p=1274, place="Crag'rog", was=3419}, -- 3431
