  {t="A", q=94768, name="Bring Me His Head", group=true, foreverOnly=true, z=16591, x=33.47, y=37.93, target={kind="npc", id=258570, name="Da'grosh"}, note="Da'grosh", tip="Overlord Kilgar is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised.", turnedIn={94745}, section="Riverglades (41-44)", zoneName="Riverglades", p=1276, place="Bring Me His Head", was=3422}, -- 3434
