  {t="G", text="Twilight's Shroud", z=16591, x=32.0, y=29.9, tip="The next guide flies from Kargath in the Badlands: north out of Da'grosh's valley and up through Twilight's Shroud, the way through to the Badlands.", section="Riverglades (41-44)", zoneName="Riverglades", p=1277, place="Twilight's Shroud"}, -- 3437
  {t="G", text="Badlands", tip="Across the Badlands to Kargath, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress.", section="Riverglades (41-44)", p=1278, place="Kargath"}, -- 3438
  {t="FP", text="Kargath flight path", section="Riverglades (41-44)", p=1278, place="Kargath"}, -- 3439
  {t="G", text="Kargath flight master", z=33, x=4.1, y=44.9, tip="Coming from the Riverglades: Kargath's flight master stands at the foot of the fortress.", inZone="Badlands", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1279, place="Fly to Grom'gol"}, -- 3440
  {t="F", text="Grom'gol", inZone="Badlands", section="Feralas & Tanaris (43-46)", p=1279, place="Fly to Grom'gol"}, -- 3441
