  {t="F", text="Grom'gol", inZone="Swamp of Sorrows", section="Feralas & Tanaris (43-46)", p=1280, place="Fly to Grom'gol"}, -- 3443
  {t="A", q=586, name="Speaking with Gan'zulah", z=33, x=32.22, y=27.6, target={kind="object", id=2076, name="Bubbling Cauldron"}, note="the Bubbling Cauldron: Speaking with Gan'zulah", tip="The flight lands at Grom'gol. Stranglethorn's harder errands, carried from your first visit, fit you now: the Skullsplitter chief, Zanzil's camps, Booty Bay's pirates, the naga coast and Mokk, before the zeppelin to Orgrimmar. The Bubbling Cauldron beside Nimboya has the Skullsplitter chief's quest.", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1281, place="Grom'gol Base Camp", was=3432}, -- 3444
  {t="C", q=586, obj=1, name="Speaking with Gan'zulah", z=33, x=45.56, y=38.64, note="Skullsplitter Hunter walks around here: look inside the circle on the map", tip="Careful: Mogh the Undying, an elite troll (level 44), stands in the southern ruins around 47.7,44.3: pull the headhunters and berserkers away from him.", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1282, place="Zul'Mamwe", was=3433}, -- 3445
  {t="C", q=586, obj=2, name="Speaking with Gan'zulah", gv="Kill", gw="Skullsplitter Headhunter", z=33, x=47.68, y=42.53, note="Kill Skullsplitter Headhunter", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1282, place="Zul'Mamwe", was=3434}, -- 3446
  {t="C", q=586, obj=3, name="Speaking with Gan'zulah", gv="Kill", gw="Skullsplitter Berserker", z=33, x=47.85, y=42.96, note="Kill Skullsplitter Berserker", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1282, place="Zul'Mamwe", was=3435}, -- 3447
