  {t="T", q=586, name="Speaking with Gan'zulah", z=33, x=32.22, y=27.6, target={kind="object", id=2076, name="Bubbling Cauldron"}, note="the Bubbling Cauldron", tip="Back west to Grom'gol.", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1283, place="Grom'gol Base Camp", was=3437}, -- 3449
