  {t="T", q=588, name="The Fate of Yenniku", z=33, x=32.27, y=27.71, target={kind="npc", id=2519, name="Kin'weelay"}, note="Kin'weelay", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1283, place="Grom'gol Base Camp", was=3439}, -- 3451
  {t="A", q=589, name="The Singing Crystals", z=33, x=32.27, y=27.71, target={kind="npc", id=2519, name="Kin'weelay"}, note="Kin'weelay: the basilisks bask beside the road south, on the ride to Booty Bay", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1283, place="Grom'gol Base Camp", was=3440}, -- 3452
  {t="C", q=589, name="The Singing Crystals", z=33, x=42.71, y=45.84, note="Below ground", tip="Ride south along the road towards Booty Bay; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often.", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1284, place="Ironjaw Basilisks", was=3441}, -- 3453
  {t="N", text="Kill Chucky \"Ten Thumbs\"", z=33, x=40.0, y=58.2, tip="Careful: the Zanzil Witch Doctors (44) cast and the camps are packed: pull from the edge, one at a time. Zanzil the Outcast (46) himself stands in the southern camp around 39.6,58.6, a few steps from Chucky's ghost: pull Chucky out to the north or east before you fight him.", section="Feralas & Tanaris (43-46)", zoneName="Stranglethorn Vale", p=1285, place="Pirate ghosts and Zanzil's camps"}, -- 3454
