  {t="C", q=7730, obj=1, name="Zukk'ash Infestation", gv="Collect", gw="Zukk'ash Carapace", z=357, x=76.22, y=59.25, note="Collect Zukk'ash Carapace", tip="Careful: Stinglasher is level 47: clear the hive around him and pull him alone at full health.", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1335, place="The Writhing Deep", was=3602}, -- 3614
  {t="C", q=7731, obj=1, name="Stinglasher", gv="Collect", gw="Stinglasher's Glands", z=357, x=75.6, y=60.9, note="Collect Stinglasher's Glands", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1335, place="The Writhing Deep", was=3603}, -- 3615
  {t="C", q=2980, obj=3, name="The Ogres of Feralas", z=357, x=61.11, y=57.53, note="Gordunni Mauler walks around Ruins of Isildien: look inside the circle on the map", tip="Careful: the Mage-Lords (45-46) and the Shamans cast from range and the ruins are packed: pull one at a time from the edge.", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1336, place="Ruins of Isildien: kill these as you meet them", was=3604}, -- 3616
  {t="C", q=2980, obj=2, name="The Ogres of Feralas", gv="Kill", gw="Gordunni Warlock", z=357, x=60.62, y=57.63, note="Kill Gordunni Warlock", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1336, place="Ruins of Isildien: kill these as you meet them", was=3605}, -- 3617
  {t="C", q=2980, obj=1, name="The Ogres of Feralas", gv="Kill", gw="Gordunni Shaman", z=357, x=60, y=63.28, note="Kill Gordunni Shaman", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1336, place="Ruins of Isildien: kill these as you meet them", was=3606}, -- 3618
  {t="C", q=2979, obj=1, name="Dark Ceremony", gv="Collect", gw="Gordunni Orb", z=357, x=60.27, y=67.24, note="Collect Gordunni Orb", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1336, place="Ruins of Isildien: kill these as you meet them", was=3607}, -- 3619
  {t="C", q=2822, obj=1, name="The Mark of Quality", gv="Collect", gw="Thick Yeti Hide", z=357, x=55.88, y=58.81, note="Collect Thick Yeti Hide", tip="North-west of the ruins, the yetis den in Feral Scar Vale; every yeti there can drop a thick hide.", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1337, place="Feral Scar Vale yetis", was=3608}, -- 3620
  {t="N", text="Collect OOX-22/FE Distress Beacon", optional=true, tip="Careful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock.", section="Feralas & Tanaris (43-46)", p=1338, place="Homing Robot OOX-22/FE"}, -- 3621
  {t="A", q=2766, name="Find OOX-22/FE!", optional=true, z=357, x=55.88, y=58.81, target={kind="item", id=8705, name="OOX-22/FE Distress Beacon"}, section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1338, place="Homing Robot OOX-22/FE", was=3610}, -- 3622
  {t="T", q=2766, name="Find OOX-22/FE!", optional=true, z=357, x=53.35, y=55.7, target={kind="npc", id=7807, name="Homing Robot OOX-22/FE"}, section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1338, place="Homing Robot OOX-22/FE", was=3611}, -- 3623
  {t="A", q=2767, name="Rescue OOX-22/FE!", optional=true, z=357, x=53.35, y=55.7, target={kind="npc", id=7807, name="Homing Robot OOX-22/FE"}, section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1338, place="Homing Robot OOX-22/FE", was=3612}, -- 3624
  {t="C", q=2767, name="Rescue OOX-22/FE!", optional=true, z=357, x=55.88, y=58.81, section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1338, place="Homing Robot OOX-22/FE", was=3613}, -- 3625
  {t="T", q=7730, name="Zukk'ash Infestation", z=357, x=74.91, y=42.46, target={kind="npc", id=7875, name="Hadoken Swiftstrider"}, note="Hadoken Swiftstrider", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1339, place="Camp Mojache", was=3614}, -- 3626
  {t="T", q=7731, name="Stinglasher", z=357, x=74.91, y=42.46, target={kind="npc", id=7875, name="Hadoken Swiftstrider"}, section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1339, place="Camp Mojache", was=3615}, -- 3627
  {t="T", q=2822, name="The Mark of Quality", z=357, x=74.43, y=42.91, target={kind="npc", id=7854, name="Jangdor Swiftstrider"}, note="Jangdor Swiftstrider, inside", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1339, place="Camp Mojache", was=3616}, -- 3628
  {t="A", q=7734, name="Improved Quality", z=357, x=74.43, y=42.91, target={kind="npc", id=7854, name="Jangdor Swiftstrider"}, note="the Rage Scar yetis, on the next visit to Feralas", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1339, place="Camp Mojache", was=3617}, -- 3629
  {t="A", q=7732, name="Zukk'ash Report", z=357, x=74.91, y=42.46, target={kind="npc", id=7875, name="Hadoken Swiftstrider"}, note="Hadoken Swiftstrider: for Zilzibin Drumlore in Orgrimmar", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1339, place="Camp Mojache", was=3618}, -- 3630
  {t="T", q=2980, name="The Ogres of Feralas", z=357, x=75.8, y=43.58, target={kind="npc", id=7777, name="Rok Orhan"}, note="Rok Orhan walks around Camp Mojache: look inside the circle on the map", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1339, place="Camp Mojache", was=3619}, -- 3631
  {t="T", q=2979, name="Dark Ceremony", z=357, x=75.8, y=43.58, target={kind="npc", id=7777, name="Rok Orhan"}, note="Rok Orhan", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1339, place="Camp Mojache", was=3620}, -- 3632
  {t="A", q=3002, name="The Gordunni Orb", z=357, x=75.8, y=43.58, target={kind="npc", id=7777, name="Rok Orhan"}, note="for Orgrimmar, after Shen'dralas", section="Feralas & Tanaris (43-46)", zoneName="Feralas", p=1339, place="Camp Mojache", was=3621}, -- 3633
  {t="N", text="Shen'dralas is next, a ride north from Camp Mojache into Desolace: keep your Orgrimmar hand-ins (Neeru, Zilzibin, Belgrom, Uthel'nay) for the flight there after it.", section="Feralas & Tanaris (43-46)", p=1339, place="Camp Mojache"}, -- 3634
  {t="G", text="Desolace, where the road from Feralas comes in", z=405, x=43.0, y=96.0, tip="Shen'dralas lies south of Desolace, through the Valley of Bones, and has no flight path of its own. From Camp Mojache ride north-west on the road past Dire Maul and on north into Desolace: the road comes out on Desolace's southern edge.", inZone="Feralas", section="Shen'dralas (46-47)", zoneName="Desolace", p=1340, place="North into Desolace"}, -- 3635
  {t="G", text="Orgrimmar flight master", z=405, x=45.3, y=63.7, tip="Shen'dralas lies south of Desolace, through the Valley of Bones, and has no flight path of its own. Its quests are for levels 41-45. Coming from the Eastern Kingdoms, take the zeppelin to Orgrimmar first (from Grom'gol or the Undercity).", notInZone="Feralas", section="Shen'dralas (46-47)", zoneName="Desolace", p=1341, place="Fly to Shadowprey Village"}, -- 3636
  {t="F", text="Shadowprey Village", notInZone="Feralas", section="Shen'dralas (46-47)", p=1341, place="Fly to Shadowprey Village"}, -- 3637
  {t="G", text="Shen'dralas", z=16651, x=21.2, y=22.4, tip="Ride east along Desolace's southern edge (from Shadowprey Village: past Gelkis Village): the Valley of Bones opens there into Shen'dralas.", notInZone="Shen'dralas", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1342, place="Into the Valley of Bones"}, -- 3638
  {t="N", text="Collect Tattered Journal", tip="The Gelkis and Magram centaurs have Valley of Bones quest chains of their own, worth about 20,000 to 30,000 more experience, but each chain asks for Honored with its clan. The two clans are rivals, so work for one of them: the Gelkis and Magram Centaur Reputation guide, under Reputation, shows how.", section="Shen'dralas (46-47)", p=1343, place="The Valley of Bones: a Tattered Journal"}, -- 3639
  {t="A", q=93644, name="Tattered Journal", foreverOnly=true, section="Shen'dralas (46-47)", p=1343, place="The Valley of Bones: a Tattered Journal", was=3628}, -- 3640
  {t="A", q=92914, name="Strange Pylons", foreverOnly=true, z=16651, x=43.64, y=34.3, target={kind="object", id=577959, name="Shen'dralar Pylon"}, tip="East through the valley to the strange crystal on its pedestal: clicking it starts Strange Pylons. The Decrepit Pylon Protectors (levels 42-43) around it are the mana elementals that guard it. Corpsefeeders (level 45, elite) roam the valley east of here.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1344, place="The western pylon", was=3629}, -- 3641
  {t="G", text="the eastern pylon", z=16651, x=73.2, y=23.2, tip="East along the valley road to the quilboar of Bristleback Retreat: the second pylon stands at the eastern end of their camp. A Corpsefeeder (level 45, elite) walks this road: let it pass. The Bristlebacks (levels 42-43) attack on sight; Kog'thug the Brave (level 43, elite) and his bodyguards hold the south side of the camp.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1345, place="Bristleback Retreat: the eastern pylon"}, -- 3642
  {t="C", q=92914, name="Strange Pylons", foreverOnly=true, z=16651, x=47.6, y=76.7, tip="South to the Shen'dralar temple at the zone's heart, keeping west of Kog'thug's bodyguards: the third pylon stands inside. The temple's guards are neutral: leave them be.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1346, place="The temple of Shen'dralas: the third pylon", was=3631}, -- 3643
  {t="T", q=93644, name="Tattered Journal", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, tip="North-west from the temple to Mordent Evenshade's camp on the overlook, beside the spirit healer: the Tattered Journal is his, and he wants to hear about the pylons.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1347, place="Evenshade's Overlook", was=3632}, -- 3644
  {t="T", q=92914, name="Strange Pylons", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1347, place="Evenshade's Overlook", was=3633}, -- 3645
  {t="A", q=96010, name="Fragments of the Pylons", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1347, place="Evenshade's Overlook", was=3634}, -- 3646
  {t="G", text="Desolace", z=405, x=64.0, y=80.4, tip="Careful: if you have killed Magram or Gelkis centaurs, that clan's guards may attack you when you walk into its village.", section="Shen'dralas (46-47)", zoneName="Desolace", p=1348, place="North into Desolace"}, -- 3647
  {t="C", q=96010, obj=1, name="Fragments of the Pylons", gv="Collect", gw="1 Pylon Fragment", foreverOnly=true, z=405, x=68.1, y=79.2, note="Collect 1 Pylon Fragment", tip="The Pylon Fragment lies at the western edge of the village; Magram Guardians (levels 39-41) watch over it.", section="Shen'dralas (46-47)", zoneName="Desolace", p=1349, place="Magram Village", was=3636}, -- 3648
  {t="C", q=96010, obj=2, name="Fragments of the Pylons", gv="Collect", gw="1 Pylon Shard", foreverOnly=true, z=405, x=36.1, y=85.6, note="Collect 1 Pylon Shard", tip="West along Desolace's southern edge to Gelkis Village: the Pylon Shard lies at its southern end, watched by Gelkis Guardians (levels 39-41).", section="Shen'dralas (46-47)", zoneName="Desolace", p=1350, place="Gelkis Village", was=3637}, -- 3649
  {t="G", text="Shen'dralas", z=16651, x=21.2, y=22.4, tip="East again along Desolace's southern edge: the Valley of Bones opens into Shen'dralas.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1351, place="Back into the Valley of Bones"}, -- 3650
  {t="T", q=96010, name="Fragments of the Pylons", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1352, place="Evenshade's Overlook", was=3639}, -- 3651
  {t="A", q=96018, name="Powering the Pylons", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1352, place="Evenshade's Overlook", was=3640}, -- 3652
  {t="N", text="Collect Mana Sieve", z=16651, x=45.9, y=78.2, tip="Mordent sends you for the Mana Sieve, kept inside the temple beside Historian Biraxas. Powering the Pylons asks you to gather mana with the Sieve before you repair the pylons: with it in your bags you can handle the Unstable Mana Rifts, the floating sparks of mana all along the road north.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1353, place="The temple: the Mana Sieve"}, -- 3653
  {t="C", q=96018, obj=2, name="Powering the Pylons", foreverOnly=true, z=16651, x=43.97, y=35.59, note="Decrepit Pylon Protector, then Repair and Recharge Pylon on it", tip="Careful: the pylon stands at the edge of the Valley of Bones, where Magram Necrokhans and Corpsefeeders (elites, level 45) walk, and Nascent Pylon Protectors (elites, 43) wander the road. Pull the Decrepit Pylon Protectors away from them before you repair it.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1354, place="The western pylon: repair it", was=3642}, -- 3654
  {t="C", q=96018, obj=3, name="Powering the Pylons", foreverOnly=true, z=16651, x=73.4, y=23.91, note="Decrepit Pylon Protector, then Repair and Recharge Pylon on it", tip="East along the valley road to the eastern pylon and repair it the same way, a Decrepit Pylon Protector first, coming in from the west: Kog'thug the Brave (level 43, elite) and his bodyguards hold the south side of the quilboar camp, and a Corpsefeeder (level 45, elite) walks the road.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1355, place="Bristleback Retreat: repair the eastern pylon", was=3643}, -- 3655
  {t="T", q=96018, name="Powering the Pylons", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, tip="Back west along the valley road and south to Mordent. A Brief History Lesson asks you to hear him out: talk to him once more, then hand it in.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1356, place="Evenshade's Overlook", was=3644}, -- 3656
  {t="A", q=93016, name="A Brief History Lesson", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1356, place="Evenshade's Overlook", was=3645}, -- 3657
  {t="C", q=93016, obj=1, name="A Brief History Lesson", foreverOnly=true, z=16651, x=35.17, y=46.61, note="Mordent Evenshade: hear him out", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1356, place="Evenshade's Overlook", was=3646}, -- 3658
  {t="T", q=93016, name="A Brief History Lesson", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1356, place="Evenshade's Overlook", was=3647}, -- 3659
  {t="A", q=93394, name="Meeting the Magister", foreverOnly=true, z=16651, x=35.17, y=46.61, target={kind="npc", id=253471, name="Mordent Evenshade"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1356, place="Evenshade's Overlook", was=3648}, -- 3660
  {t="A", q=93568, name="Partially Digested Collar", foreverOnly=true, z=16651, x=47.46, y=65.63, tip="A Prowler gave up a Partially Digested Collar: Liranne, north of the temple, knows whose it was.", hasAtLeast={259461, 1}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1357, place="Liranne", was=3649}, -- 3661
  {t="T", q=93568, name="Partially Digested Collar", foreverOnly=true, z=16651, x=47.46, y=65.63, target={kind="npc", id=255385, name="Liranne"}, hasAtLeast={259461, 1}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1357, place="Liranne", was=3650}, -- 3662
  {t="T", q=93394, name="Meeting the Magister", foreverOnly=true, z=16651, x=47.37, y=76.46, target={kind="npc", id=254656, name="Magister Kirandis"}, tip="Magister Kirandis waits inside the temple. Then Mithera, on the temple's eastern side, has work in the Forlorn Gardens.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1358, place="The temple: Magister Kirandis", was=3651}, -- 3663
  {t="A", q=93341, name="Forlorn Gardens", foreverOnly=true, z=16651, x=53.32, y=76.02, target={kind="npc", id=254578, name="Mithera"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1358, place="The temple: Magister Kirandis", was=3652}, -- 3664
  {t="C", q=93341, name="Forlorn Gardens", foreverOnly=true, z=16651, x=70.3, y=79.7, tip="East of the temple the Forlorn Gardens have run wild, and their plants attack on sight. Examine the pedestal at the gardens' southern end.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1359, place="The Forlorn Gardens: the pedestal", was=3653}, -- 3665
  {t="T", q=93341, name="Forlorn Gardens", foreverOnly=true, z=16651, x=53.32, y=76.02, target={kind="npc", id=254578, name="Mithera"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1360, place="Mithera", was=3654}, -- 3666
  {t="A", q=93362, name="What They've Done to My Peonies", foreverOnly=true, z=16651, x=53.32, y=76.02, target={kind="npc", id=254578, name="Mithera"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1360, place="Mithera", was=3655}, -- 3667
  {t="A", q=93594, name="Word of the Woods", foreverOnly=true, z=16651, x=53.32, y=76.02, target={kind="npc", id=254578, name="Mithera"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1360, place="Mithera", was=3656}, -- 3668
  {t="C", q=93362, obj=1, name="What They've Done to My Peonies", foreverOnly=true, z=16651, x=57.04, y=73.14, note="Rowdy Rose", tip="The Shen'dralar who wander the gardens are neutral, like the temple's guards: leave them be and pull the flowers away from them. Careful: Nascent Pylon Protectors (elites, 43) wander the zone's middle, the gardens too: keep clear of them.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1361, place="The Forlorn Gardens", was=3657}, -- 3669
  {t="C", q=93362, obj=2, name="What They've Done to My Peonies", foreverOnly=true, z=16651, x=59.88, y=72.57, note="Terrible Tulip", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1361, place="The Forlorn Gardens", was=3658}, -- 3670
  {t="C", q=93362, obj=3, name="What They've Done to My Peonies", foreverOnly=true, z=16651, x=63.06, y=70.97, note="Malevolent Marigold", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1361, place="The Forlorn Gardens", was=3659}, -- 3671
  {t="T", q=93594, name="Word of the Woods", foreverOnly=true, z=16651, x=69.66, y=71.78, target={kind="npc", id=254674, name="Woodwyrd"}, section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1361, place="The Forlorn Gardens", was=3660}, -- 3672
  {t="T", q=93362, name="What They've Done to My Peonies", foreverOnly=true, z=16651, x=53.32, y=76.02, target={kind="npc", id=254578, name="Mithera"}, tip="Historian Biraxas, inside the temple, has a task for you now that you have met Magister Kirandis: the heart of a Decrepit Pylon Protector (42-43, not elite), a short ride back up the road north.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1362, place="Mithera", was=3661}, -- 3673
  {t="A", q=99257, name="A Heart of Crystal", foreverOnly=true, z=16651, x=46, y=78.22, target={kind="npc", id=255486, name="Historian Biraxas"}, note="Historian Biraxas", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1362, place="Mithera", was=3662}, -- 3674
  {t="C", q=99257, obj=1, name="A Heart of Crystal", gv="Collect", gw="Depleted Crystal Heart", foreverOnly=true, z=16651, x=44.72, y=44.48, note="Collect Depleted Crystal Heart", tip="The nearest Decrepit Pylon Protectors stand by the road north, from the middle of the zone up to the western pylon, and around Mordent's overlook: one of them carries the heart Biraxas wants.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1363, place="A Heart of Crystal", was=3663}, -- 3675
  {t="T", q=99257, name="A Heart of Crystal", foreverOnly=true, z=16651, x=46, y=78.22, target={kind="npc", id=255486, name="Historian Biraxas"}, tip="Shen'dralas is done: ride back north through the Valley of Bones; the next step says where your route goes on from there.", section="Shen'dralas (46-47)", zoneName="Shen'dralas", p=1364, place="Historian Biraxas", was=3664}, -- 3676
  {t="G", text="Shadowprey Village flight master", z=1637, x=21.56, y=74.04, tip="Shen'dralas is done. Ride back north through the Valley of Bones and west along Desolace's southern edge to Shadowprey Village: the next guide picks up in Orgrimmar, with the Feralas guide's hand-ins. Your hearthstone is bound at Camp Mojache: if it is ready, hearth there and fly to Orgrimmar from Camp Mojache instead.", section="Shen'dralas (46-47)", zoneName="Orgrimmar", p=1365, place="Shadowprey Village"}, -- 3677
