  {t="T", q=992, name="Gadgetzan Water Survey", z=440, x=50.21, y=27.48, target={kind="npc", id=7724, name="Senior Surveyor Fizzledowser"}, note="Senior Surveyor Fizzledowser", tip="Back east to Fizzledowser on the west side of Gadgetzan; Marvon is south from there.", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1414, place="Senior Surveyor Fizzledowser", was=3790}, -- 3803
