  {t="A", q=3161, name="Gahz'ridian", z=440, x=52.71, y=45.92, target={kind="npc", id=7771, name="Marvon Rivetseeker"}, tip="West along the road south; Marvon camps by the ruins at the Broken Pillar. Put on his Gahz'ridian Detector: it shows the buried ornaments, here and around the Dunemaul Compound.", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1415, place="Marvon Rivetseeker", was=3792}, -- 3805
  {t="C", q=3161, obj=1, name="Gahz'ridian", gv="Collect", gw="Gahz'ridian Ornament", z=440, x=52.3, y=45.3, note="Collect Gahz'ridian Ornament", tip="Dig up the Gahz'ridian ornaments around the Broken Pillar and north of the Dunemaul Compound. Leave the ogres for now: Gor'marok the Ravager is 49 and the Brutes 46-48; the Dunemaul Compound comes at the end of 40-50/06, at about 52.", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1416, place="Gahz'ridian ornaments", was=3793}, -- 3806
  {t="C", q=82, obj=1, name="Noxious Lair Investigation", gv="Collect", gw="Centipaar Insect Parts", z=440, x=36.26, y=45.05, note="Collect Centipaar Insect Parts", tip="Careful: Centipaar Swarmers cast Silithid Swarm both in and out of combat, which brings small adds that interrupt you. The Sandreavers are 49-50: take the Workers and Tunnelers.", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1417, place="The Noxious Lair", was=3794}, -- 3807
  {t="N", text="Collect OOX-17/TN Distress Beacon", optional=true, note="OOX-17/TN Distress Beacon, a rare drop", tip="Careful: The other thistleshrub mobs in the area are level 48-50 and wander a lot, so you can easily pull extra mobs: take the Dew Collectors at the valley's edge, and leave Tran'rek's Gnarled Thistleshrubs and Rootshapers for the Broken Pillar ride into Un'Goro at about 51.", section="Tanaris & Searing Gorge (48-49)", p=1418, place="Thistleshrub Valley: kill these as you meet them"}, -- 3808
  {t="C", q=2605, obj=1, name="The Thirsty Goblin", gv="Collect", gw="Laden Dew Gland", z=440, x=29.2, y=66.1, note="Collect Laden Dew Gland", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1418, place="Thistleshrub Valley: kill these as you meet them", was=3796}, -- 3809
  {t="A", q=1560, name="Tooga's Quest", z=440, x=30, y=65, target={kind="npc", id=5955, name="Tooga"}, note="Tooga", tip="Tooga waits in the valley. Walk him all the way to his wife Torta in Steamwheedle Port, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. Yeh'kinya stands in the port too.", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1419, place="Tooga's escort", was=3797}, -- 3810
  {t="C", q=1560, name="Tooga's Quest", z=440, x=66.58, y=25.67, section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1419, place="Tooga's escort", was=3798}, -- 3811
  {t="T", q=1560, name="Tooga's Quest", z=440, x=66.58, y=25.67, target={kind="npc", id=6015, name="Torta"}, note="Torta, Steamwheedle Port", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1420, place="Steamwheedle Port", was=3799}, -- 3812
  {t="T", q=3520, name="Screecher Spirits", z=440, x=66.99, y=22.36, target={kind="npc", id=8579, name="Yeh'kinya"}, note="Yeh'kinya", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1420, place="Steamwheedle Port", was=3800}, -- 3813
  {t="C", q=379, obj=1, name="Slake That Thirst", gv="Collect", gw="Wastewander Water Pouch", z=440, x=60.0, y=23.4, note="Collect Wastewander Water Pouch", tip="Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and Shadow Bolt. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less.", section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1421, place="Slake That Thirst", was=3801}, -- 3814
  {t="T", q=379, name="Slake That Thirst", z=440, x=52.46, y=28.51, target={kind="npc", id=7407, name="Chief Engineer Bilgewhizzle"}, section="Tanaris & Searing Gorge (48-49)", zoneName="Tanaris", p=1422, place="Gadgetzan", was=3802}, -- 3815
  {t="N", text="Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts Tanaris Field Sampling, a two-hour timer, so use it on the way back north from Scrimshank's hive.", section="Tanaris & Searing Gorge (48-49)", p=1422, place="Gadgetzan"}, -- 3816
