  {t="N", text="Keep the parcel: Royal Overseer Bauhaus is in the Undercity. The next guide starts with Mulgris Deepriver by the Writhing Haunt, south-east of here.", section="Un'Goro Crater, Burning Steppes & Western Plaguelands (51-53)", p=1599, place="Janice Felstone"}, -- 4265
  {t="A", q=4984, name="The Wildlife Suffers Too", z=28, x=53.73, y=64.66, target={kind="npc", id=10739, name="Mulgris Deepriver"}, note="Inside", tip="He camps by the Writhing Haunt, south-east of Dalson's Tears.", section="Felwood & Western Plaguelands (52-55)", zoneName="Western Plaguelands", p=1600, place="Mulgris Deepriver", was=4253}, -- 4266
